import json
from pathlib import Path
from PIL import Image

BASE=Path(__file__).resolve().parent
MAP={x['pdf']:x['printed'] for x in json.loads((BASE/'source_map.json').read_text(encoding='utf8'))['pages']}
def src(a,b=None):
    ps=list(range(a,(b or a)+1)); return {'pdf':ps,'printed':[MAP[p] for p in ps if MAP[p] is not None]}
def p(t): return {'type':'p','text':t}
def bullets(*xs): return {'type':'bullets','items':list(xs)}
def steps(title,*xs): return {'type':'steps','title':title,'items':list(xs)}
def tab(headers,rows): return {'type':'table','headers':headers,'rows':rows}
def formula(text,explanation,symbols=[]): return {'type':'formula','text':text,'symbols':symbols,'explanation':explanation}
def sec(n,t,a,b,*blocks): return {'number':n,'title':t,'source':src(a,b),'blocks':list(blocks)}
def chapter(n,title,a,b,overview,flow):
    return {'id':f'O{n:02}','order':n,'title':f'제{n}장. {title}','source':src(a,b),'overview':overview,'flow':flow,'sections':[],'codes':[],'figures':[],'key_points':[],'comparisons':[],'review':[],'checklist':[],'index_terms':[],'coverage':[],'limitations':[],'verification':{'read_pdf_pages':list(range(a,b+1)),'visually_checked_pdf_pages':[],'notes':[]}}
def fig(c,pdf,ident,title,bbox,meaning):
    image=BASE/'images'/f'{pdf:04}.jpg'; out=BASE/'assets'/f'{ident}.png'
    im=Image.open(image); w,h=im.size
    box=[round(bbox[0]*w),round(bbox[1]*h),round(bbox[2]*w),round(bbox[3]*h)]
    im.crop(tuple(box)).save(out)
    c['figures'].append({'id':ident,'title':title,'file':str(out),'source':src(pdf),'caption':title+' — 원문 그림 부분 발췌','meaning':meaning,'crop':{'image':str(image),'bbox':box}})
    c['verification']['visually_checked_pdf_pages'].append(pdf)
    return {'type':'figure_ref','id':ident}
def finish(c):
    c['coverage']=[{'number':s['number'],'title':s['title'],'source':s['source'],'topics':[b.get('text',b.get('title',b['type']))[:150] for b in s['blocks']]} for s in c['sections']]
    for s in c['sections']:
        c['checklist'].append({'text':s['title']+'의 핵심 개념·조건·처리 관계를 설명할 수 있는가?','source':s['source']})
    c['verification']['visually_checked_pdf_pages']=sorted(set(c['verification']['visually_checked_pdf_pages']))
    (BASE/'chapters'/f"{c['order']:02}.json").write_text(json.dumps(c,ensure_ascii=False,indent=2),encoding='utf8')

c=chapter(11,'대용량 저장장치 구조',430,473,
 ['HDD와 비휘발성 메모리(NVM)의 물리적 차이가 주소 매핑, 스케줄링, 오류 처리에 미치는 영향을 살펴본다. 저장장치 초기화·부팅·스왑 공간·연결 방식과 RAID의 신뢰성 및 성능을 연결해 정리한다.'],
 ['HDD/NVM의 구조와 논리 블록 → 요청 스케줄링 → 오류 감지·수정 → 포매팅·부팅·손상 블록 → 스왑 → 연결 구조 → RAID와 객체 저장소'])
c['sections']=[
sec('11.1','대용량 저장장치 구조의 개관',430,438,
 p('**대용량 저장장치**는 비휘발성 정보를 보관한다. 원문은 HDD와 NVM을 주요 보조저장장치로, 자기 테이프·광디스크·클라우드 저장장치 등을 느리고 큰 3차 저장장치의 예로 다룬다. 여러 종류를 함께 지칭할 때 NVS(nonvolatile storage) 또는 드라이브라고 한다. 물리 장치의 특성은 운영체제의 주소 매핑을 거쳐 논리 저장장치로 제공된다.')),
sec('11.1.1','하드 디스크 드라이브',431,432,
 p('**HDD**는 자기 물질로 덮인 원형 플래터에 정보를 기록하고, 각 표면 위의 읽기-쓰기 헤드가 자기 패턴을 감지한다. 헤드들은 디스크 암에 붙어 함께 이동한다. 원형 **트랙**은 다시 **섹터**로 나뉘며, 같은 암 위치의 트랙 집합이 **실린더**이다. 섹터는 크기가 고정된 최소 전송 단위이다.'),
 p('전송률은 드라이브와 컴퓨터 사이의 데이터 흐름 속도이며, 위치 지정 시간(임의 접근 시간)은 원하는 실린더로 암을 옮기는 **탐색 시간**과 원하는 섹터가 헤드 아래까지 도는 **회전 지연시간**으로 구성된다. 컨트롤러의 DRAM 버퍼는 성능을 높인다. 공표된 전송률은 매체에서 비트를 읽는 비율일 수 있으므로 운영체제에 블록이 실제 전달되는 전송률과 구별해야 한다.'),
 p('헤드는 매우 얇은 공기나 가스층 위에서 움직인다. 표면에 닿는 **헤드 충돌**은 자기 표면을 손상시키며 일반적으로 수리할 수 없다. 드라이브 전체를 교체해야 할 수 있고, 다른 저장장치나 RAID로 보호하지 않은 데이터는 손실된다. 일부 섀시는 시스템 종료 없이 드라이브를 제거·교체할 수 있다.')),
sec('11.1.2','비휘발성 메모리 장치와 NAND 컨트롤러',433,435,
 p('**NVM 장치**는 기계식이 아닌 전기식이다. 원문은 컨트롤러와 플래시 NAND 다이로 구성되는 장치에 초점을 맞춘다. 디스크와 유사한 외형이면 SSD라고 하며, USB 드라이브나 메모리 스틱 형태 또는 기판에 직접 실장하는 형태도 같은 원리로 취급한다. 움직이는 부분이 없어 HDD보다 안정적이고 탐색·회전 지연이 없으며 전력 소비도 적다. 반면 원문이 비교하는 시점에서는 메가바이트당 가격이 비싸고 대형 HDD보다 용량이 작다. 버스가 성능을 제한할 수 있어 시스템 버스에 직접 연결하기도 한다.'),
 p('NAND는 **페이지** 단위로 읽고 쓰지만 기존 데이터를 그대로 덮어쓸 수 없다. 덮어쓰려면 먼저 지워야 하며, 지우기는 여러 페이지로 된 **블록** 단위이다. 읽기가 가장 빠르고, 쓰기는 읽기보다 느리지만 지우기보다는 훨씬 빠르다. 여러 다이와 데이터 경로를 이용한 병렬 처리가 가능하다. 지우기마다 셀이 열화되므로 쓰기 마모가 수명을 제한한다. DWPD(Drive Writes Per Day)는 보증 기간 동안 하루에 드라이브 전체 용량만큼 데이터를 몇 번 쓸 수 있는지를 나타낸다.'),
 steps('FTL·가비지 수집·과잉 공급의 관계','블록이 다시 기록되면 새 페이지가 현재 데이터를 보유하고 이전 페이지의 데이터는 무효가 된다. 플래시 변환 계층(FTL)은 유효한 논리 블록을 실제 페이지로 매핑하고 물리 블록 상태를 추적한다.','공간이 부족하면 유효하지 않은 페이지만 든 블록을 지운다. 유효·무효 페이지가 섞인 블록은 유효 데이터를 다른 위치로 복사한 뒤 지운다. 이것이 가비지 수집이다.','이 복사를 위한 여유 공간과 쓰기 성능을 확보하려고 장치는 과잉 공급 영역을 따로 둔다. 지운 블록은 장치 상태에 따라 과잉 공급 공간이나 가용 풀로 돌아간다.','삭제 횟수가 적은 블록에 데이터를 배치하여 후속 지우기를 분산한다. 이러한 마모 평준화는 일부 블록만 일찍 마모되어 전체 수명이 줄어드는 것을 막는다.'),
 p('컨트롤러는 데이터와 함께 오류 수정 코드를 저장하고 읽을 때 검사한다. 수정 가능한 오류가 반복되는 페이지는 불량으로 표시하여 쓰지 않는다. 그래도 장치 전체 고장이나 데이터 오염이 가능하므로 RAID로 보호할 수 있다. 이 알고리즘들은 대체로 컨트롤러 내부에서 구현되지만 그 동작에 따라 성능이 달라진다.')),
sec('11.1.3','휘발성 메모리와 자기 테이프',435,437,
 p('**RAM 드라이브**는 시스템 DRAM의 일부를 장치 드라이버가 저장장치처럼 제공하는 것이다. raw 블록 장치로도 쓸 수 있지만 보통 파일 시스템을 만들어 표준 파일 연산으로 사용한다. 캐시·버퍼가 운영체제나 프로그래머에 의해 할당되는 것과 달리 사용자는 파일을 생성·읽기·쓰기·삭제하는 방식으로 임시 데이터를 보관한다. 매우 빠른 임시 파일·프로그램 간 데이터 공유·부팅 중 임시 루트 파일 시스템에 유용하다. 휘발성이므로 크래시·종료·전원 차단 뒤에는 내용이 지속되지 않는다.'),
 p('원문의 별도 설명에서 **자기 테이프**는 비휘발성과 큰 용량을 제공하지만 임의 위치를 찾는 데 오래 걸리므로 보조저장장치보다는 백업·잘 쓰지 않는 정보의 보관·시스템 간 전송에 적합하다. 위치를 찾은 뒤에는 HDD와 비슷한 전송 속도로 읽고 쓸 수 있다. 따라서 임의 위치 접근의 지연과 위치를 찾은 후의 순차 전송 속도를 구별해야 한다.')),
sec('11.1.4','보조저장장치 연결 방법',437,437,
 p('보조저장장치는 시스템 버스나 I/O 버스에 연결된다. 원문은 ATA·SATA·eSATA·SAS·USB·FC를 예로 들고, NVM에는 PCI 버스에 직접 연결하여 처리량을 높이고 지연을 줄이는 NVMe를 설명한다. **호스트 컨트롤러(HBA)**는 컴퓨터 쪽에서 버스 전송을 맡고, 장치 내부 컨트롤러는 실제 하드웨어를 작동시킨다.'),
 steps('명령과 데이터 전달','컴퓨터는 보통 메모리 매핑 I/O 포트로 호스트 컨트롤러에 명령을 놓는다.','호스트 컨트롤러는 장치 컨트롤러에 명령을 전달하고, 장치 컨트롤러는 드라이브를 작동시킨다.','매체와 내장 캐시 사이에서 데이터가 이동하고, 캐시와 호스트 DRAM 사이에는 DMA로 데이터가 전송된다.')),
sec('11.1.5','주소 매핑',437,438,
 p('운영체제는 저장장치를 **논리 블록의 1차원 배열**로 다룬다. 논리 블록은 최소 전송 단위이며 물리 섹터나 반도체 페이지로 매핑된다. 실린더·헤드·섹터 또는 칩·블록·페이지의 조합보다 LBA(논리 블록 주소)가 다루기 쉽다.'),
 p('현대 드라이브에서 LBA를 실제 위치로 단순 환산하기는 어렵다. 손상 섹터는 예비 섹터로 대체되고, 트랙당 섹터 수가 일정하지 않을 수 있으며, 제조업체가 내부 매핑을 관리하기 때문이다. 따라서 스케줄러는 보통 가까운 LBA가 가까운 물리 블록에 해당한다는 경향을 이용한다.'),
 tab(['구분','원문의 설명'],[['CLV(고정 선형 속도)','트랙의 비트 밀도를 일정하게 유지한다. 바깥 트랙은 길어 더 많은 섹터를 담으며, 안쪽으로 갈수록 회전 속도를 높여 데이터 비율을 유지한다. CD-ROM·DVD-ROM의 예가 제시된다.'],['CAV(고정 각 속도)','회전 속도를 일정하게 유지하며 안쪽에서 바깥쪽으로 갈수록 비트 밀도를 줄인다. 원문은 HDD에서 사용하는 방법으로 설명한다.']]),
 p('원문은 실린더를 구역으로 나누어 같은 구역 안에서는 트랙당 섹터 수를 일정하게 하고 구역 사이에서는 다르게 구성하는 방법도 설명한다. HDD와 NVM을 결합한 장치·볼륨 관리자는 일반 장치와 특성이 달라 캐싱과 스케줄링도 달라질 수 있다.')),
sec('11.2','디스크 스케줄링',439,439,
 p('HDD 관리의 목표는 접근 시간을 줄이고 전송 대역폭을 높이는 것이다. 장치 대역폭은 첫 요청부터 마지막 전송 완료까지의 전체 시간으로 총 전송 바이트 수를 나눈 값이다. I/O 시스템 콜은 읽기·쓰기 여부, 열린 파일 핸들, 메모리 주소, 데이터 양을 전달한다. 장치나 컨트롤러가 바쁘면 요청은 큐에 대기하고, 드라이버는 큐를 재정렬할 수 있다.'),
 p('현대 드라이브는 실제 헤드·트랙 위치를 호스트에 완전히 공개하지 않는다. 따라서 디스크 스케줄링은 물리적 탐색 최소화뿐 아니라 공정성·적시성·순차 요청의 병합을 고려한다. 특정 요청 집합의 최적 순서를 계산하는 비용이 얻는 이익보다 클 수도 있다.')),
sec('11.2.1','선입 선처리 스케줄링',440,440,
 p('**FCFS**는 요청이 도착한 순서대로 처리한다. 본질적으로 공평해 보이지만 빠른 서비스를 보장하지 않는다. 원문 큐는 98, 183, 37, 122, 14, 124, 65, 67이고 시작 헤드는 53이다. 이 순서 그대로 이동한 총 거리는 원문에 **640 실린더**로 제시된다. 122→14→124처럼 가까운 두 요청 사이를 크게 왕복하는 이동이 발생한다.'),
 fig(c,440,'O11-F01','그림 11.6 FCFS 디스크 스케줄링',(0.29,0.682,0.79,0.947),'동일한 요청 큐를 도착 순서로 처리할 때 헤드가 왕복하는 경로를 보인다. 총 이동거리 640은 원문에 제시된 결과이다.')),
sec('11.2.2','SCAN 스케줄링',440,441,
 p('**SCAN**은 한 방향으로 이동하면서 경로상의 요청을 모두 처리한 뒤 반대로 이동한다. 원문은 한쪽 끝 또는 그 방향에 더 이상 대기 요청이 없는 경우 방향을 바꾼다고 설명하며, 엘리베이터 알고리즘이라고도 한다. 현재 위치뿐 아니라 진행 방향도 알아야 한다. 같은 큐에서 53에서 0 방향으로 출발하면 37·14를 처리하고 0에서 반전하여 65·67·98·122·124·183을 처리한다.'),
 p('헤드 앞에 새 요청이 생기면 진행하며 처리할 수 있지만 뒤에 생기면 돌아올 때까지 기다린다. 모든 실린더에 요청이 균일하게 도착한다고 가정하면 막 통과한 쪽 끝보다 오래 방문하지 않은 반대 끝에 대기 요청이 더 많다. 이 관찰이 C-SCAN의 출발점이다.')),
sec('11.2.3','C-SCAN 스케줄링',441,442,
 p('**C-SCAN**은 대기 시간을 더 균등하게 하려는 SCAN의 변형이다. 한 방향으로 움직이며 요청을 처리하지만 끝에 도달하면 반대 방향의 요청을 처리하며 돌아오지 않고 시작 쪽으로 돌아간다. 실린더들을 마지막에서 처음으로 이어지는 순환 리스트처럼 취급한다. 원문 예는 시작 53에서 199 방향으로 이동하여 큰 실린더의 요청들을 처리하고 0으로 돌아간 뒤 14·37을 처리한다.'),
 fig(c,442,'O11-F02','그림 11.8 C-SCAN 디스크 스케줄링',(0.29,0.095,0.77,0.375),'큰 실린더 쪽 요청들을 처리한 뒤 반대 끝으로 돌아가는 경로를 표시한다. 돌아가는 구간과 요청을 처리하는 구간을 구별한다.')),
sec('11.2.4','디스크 스케줄링 알고리즘의 선택',442,443,
 p('성능은 요청 수와 유형에 좌우된다. 큐에 요청이 하나뿐이면 모든 알고리즘이 사실상 FCFS처럼 동작한다. SCAN과 C-SCAN은 부하가 큰 시스템에서 기아 가능성을 줄이지만 완전히 없애지는 않는다.'),
 p('원문의 Linux **마감시간 스케줄러**는 읽기·쓰기마다 LBA 순서 큐와 FCFS 큐를 두어 총 네 큐를 유지한다. 읽을 때 프로세스가 봉쇄될 가능성이 더 높아 읽기에 우선순위를 준다. LBA 순서로 배치를 처리한 뒤 FCFS 큐에서 오래 기다린 요청을 검사하고, 그런 요청이 있으면 그 요청이 든 LBA 큐를 다음 배치로 선택한다. 원문의 기본 대기 기준은 500ms이다.'),
 p('원문에서 NOOP는 빠른 NVM을 쓰는 CPU 중심 시스템에 적합한 단순 스케줄러이고, CFQ는 실시간·최선 노력·유휴의 세 큐를 우선순위대로 관리한다. CFQ는 이전 기록으로 같은 프로세스의 후속 I/O를 예측하여 기다림으로써 참조 지역성과 탐색 감소를 이용하지만 배타적 우선순위로 기아가 생길 수 있다. 이 설명은 책에서 제시한 배포판·버전의 사례이며 현재 설정으로 확대하지 않는다.')),
sec('11.3','NVM 스케줄링',443,444,
 p('NVM에는 움직이는 헤드가 없어 HDD의 이동 최소화 알고리즘의 이익이 작다. 보통 간단한 FCFS를 쓰며 Linux NOOP는 인접 요청을 병합한다. 읽기 서비스 시간은 일정하지만 플래시 쓰기 시간은 일정하지 않으므로 일부 SSD 스케줄러는 인접 쓰기만 병합하고 읽기는 FCFS로 처리한다.'),
 p('무작위 접근에서 HDD는 헤드 이동 때문에 제약을 받지만 NVM은 더 많은 IOPS를 처리할 수 있다. 순차 전송에서는 헤드 탐색이 적어 NVM의 상대적 이득이 작아진다. NVM 쓰기는 읽기보다 느리며, 장치가 얼마나 찼는지와 얼마나 마모되었는지에 따라 성능이 달라진다.'),
 steps('쓰기 증폭이 생기는 과정','응용의 쓰기를 위해 새 페이지를 기록해야 하지만 유효·무효 데이터가 섞인 블록에서 공간 회수가 필요하다.','유효 페이지를 읽어 과잉 공급 공간으로 복사하고, 무효 데이터만 남은 블록을 지운다.','이 블록을 다시 여유 공간에 포함한다. 응용의 한 번 쓰기에 추가 읽기와 추가 쓰기가 생긴다.'),
 p('이처럼 가비지 수집과 공간 관리를 위해 장치 자체가 생성하는 추가 I/O가 **쓰기 증폭**이다. 최악에는 매 쓰기마다 여러 I/O가 촉발된다. 파일 삭제 사실을 장치에 알려 불필요한 블록을 지우게 하는 방법은 수명과 성능 개선에 도움이 된다.')),
sec('11.4','오류 감지 및 수정',444,445,
 p('**오류 감지**는 기록·전송·보관 중 데이터가 변했는지를 알아내어 전파를 막거나 경고하는 것이다. 바이트와 함께 패리티 비트를 저장하면 모든 단일 비트 오류를 감지하지만 이중 비트 오류는 놓칠 수 있다. 패리티는 XOR로 계산할 수 있고 추가 저장 공간이 필요하다. 체크섬은 계산한 값을 저장·비교하는 방식이며 CRC도 다중 비트 오류를 감지하는 방법으로 제시된다.'),
 p('**ECC(오류 수정 코드)**는 감지뿐 아니라 일부 오류를 보정할 만큼 정보를 추가로 저장한다. 디스크는 섹터별, 플래시는 페이지별 ECC를 사용한다. 기록할 때 값을 계산해 저장하고 읽을 때 다시 계산하여 비교한다. 손상 비트가 적어 수정할 수 있으면 소프트 오류이고, ECC로 수정할 수 없으면 하드 오류이다. 가능한 수정 범위는 알고리즘과 저장한 추가 정보의 양에 좌우된다. 컨트롤러가 통상적인 읽기·쓰기 때 이 처리를 자동 수행한다.')),
sec('11.5.1','드라이브 포매팅, 파티션, 볼륨',445,447,
 p('**저수준(물리적) 포매팅**은 섹터·페이지를 컨트롤러가 읽고 쓸 수 있는 구조로 초기화한다. 헤더·데이터 영역·트레일러가 마련되며 번호와 오류 탐지·수정 정보가 저장된다. NVM은 페이지 초기화와 FTL 생성이 필요하다. HDD는 대체로 공장에서 포맷되어 나온다. 섹터가 커지면 헤더·트레일러 비중이 줄지만 운영체제가 지원하는 섹터 크기는 제한될 수 있다.'),
 steps('파일을 보유하기 위한 운영체제의 작업','파티션: 블록·페이지 그룹을 나누어 별도 장치처럼 취급한다. 파티션 정보는 정해진 형식과 위치에 기록된다.','볼륨 생성·관리: 파티션 하나를 바로 볼륨으로 쓰거나 여러 장치·파티션을 RAID 등으로 묶는다. 마운트 가능한 파일 시스템이나 파일 시스템을 담은 이미지 파일도 볼륨이라고 할 수 있다.','논리적 포매팅: 가용·할당 공간의 맵과 빈 디렉터리 등 초기 파일 시스템 자료구조를 기록한다.'),
 p('마운트하면 파일 시스템을 사용할 수 있다. Windows는 C:·D:처럼 볼륨을 구분하고 Linux는 루트에서 시작하는 트리 내부에 다른 파일 시스템을 마운트한다. 파일 시스템은 블록을 클러스터로 묶어 순차 I/O를 늘리고 파일 데이터와 메타데이터를 가까이 배치하여 탐색을 줄인다.'),
 p('**raw I/O**는 파티션을 논리 블록의 배열로 직접 쓰며 버퍼 캐시·잠금·선반입·공간 할당·이름·디렉터리 같은 파일 시스템 서비스를 우회한다. 데이터베이스나 스왑처럼 전용 관리를 원하는 경우 유용하지만 대부분의 응용은 파일 시스템을 사용한다.')),
sec('11.5.2','부트 블록',447,448,
 steps('원문의 부팅 과정','펌웨어의 작은 부트스트랩 로더가 CPU 레지스터·컨트롤러·메모리 등을 초기화한다.','아직 전체 장치 드라이버가 없을 때에도 고정 위치의 부트 블록을 읽을 만큼의 기능으로 더 큰 부트스트랩 프로그램을 적재한다.','부트스트랩 프로그램이 커널을 찾아 시작하고, 커널이 서브시스템과 서비스를 적재한다.'),
 p('원문의 Windows 예에서는 첫 논리 블록·페이지인 **MBR**에 부트 코드, 파티션 표, 부트 파티션 표시가 있다. 펌웨어가 MBR을 읽고 부트 파티션의 첫 섹터·페이지를 읽으면 그 부트 섹터가 커널로 안내한다. 부트 파티션이 있는 장치를 부트 디스크 또는 시스템 디스크라고 한다. 펌웨어는 갱신 가능하지만 악성 수정으로 감염될 수도 있다는 주의가 제시된다.')),
sec('11.5.3','손상된 블록',448,450,
 p('단순한 방식은 포맷 중이나 검사 프로그램으로 손상 블록을 찾아 파일 시스템이 할당하지 않게 표시하는 것이다. 컨트롤러가 관리하는 방식에서는 손상 목록과 운영체제에 보이지 않는 예비 섹터를 유지하고 손상 섹터를 교체한다. 이것이 **섹터 예비/포워딩**이다. 논리 주소는 같지만 실제 위치가 달라져 스케줄링 최적화를 약화시킬 수 있어 같은 실린더의 예비 섹터를 우선 사용할 수 있다.'),
 p('**섹터 밀어내기**는 손상 위치부터 예비 섹터까지 여러 섹터를 옮겨 논리적 순서를 유지하는 방법이다. 원문은 논리 블록 17의 결함과 202 뒤의 예비 섹터를 이용해 202부터 차례로 뒤로 복사하는 예를 든다. 복구 가능한 소프트 오류는 사본을 만든 뒤 교체할 수 있지만 하드 오류의 데이터는 백업 등의 개입이 필요하다. NVM은 탐색 위치를 고려할 필요가 없어 예비 페이지·과잉 공급 영역과 불량 페이지 표로 관리한다.')),
sec('11.6','스왑 공간 관리',450,452,
 p('가상 메모리는 보조저장장치를 메모리의 확장으로 쓰지만 훨씬 느리므로 스왑 설계가 성능에 크게 작용한다. 원문은 초기의 프로세스 전체 스와핑과 현대의 페이지 단위 스와핑을 구별한다. 스왑 공간의 크기는 메모리 관리 방식·물리/가상 메모리 크기에 좌우된다. 부족하면 프로세스 중단이나 시스템 크래시가 가능하고, 너무 크면 일반 파일 공간을 줄인다. 여러 장치의 스왑 영역으로 I/O 부하를 분산할 수도 있다.'),
 tab(['위치','장점·조건','제약'],[['파일 시스템의 스왑 파일','일반 파일 루틴으로 생성·삭제·관리하기 편하다.','파일 시스템을 거친다.'],['전용 raw 파티션','파일·디렉터리를 저장하지 않고 속도에 초점을 맞춘 스왑 루틴으로 관리한다. 내용이 짧게 유지되고 부팅 때 초기화된다.','고정 크기를 늘리려면 재파티션하거나 다른 스왑 공간을 추가해야 한다.']]),
 p('11.6.3의 Solaris 예는 실행 파일의 코드 페이지를 교체할 때 스왑에 쓰지 않고 버린 뒤 필요하면 파일 시스템에서 다시 읽는다. 스왑은 파일로 뒷받침되지 않는 스택·힙·미초기화 데이터 같은 **익명 메모리**의 백업에 쓴다. 이후 Solaris는 페이지 생성 시점이 아니라 실제 퇴출 시점에 스왑 공간을 할당한다.'),
 p('Linux도 익명 메모리에 스왑을 사용하며 파일이나 전용 파티션의 여러 영역을 허용한다. 원문 예의 각 영역은 연속된 4KB 페이지 슬롯으로 구성되고 **스왑 맵**의 정수 카운터가 슬롯 사용을 나타낸다. 0이면 가용, 양수이면 사용 중이며 값은 그 스왑 페이지를 공유하는 수이다. 원문 그림의 카운터 3은 세 프로세스가 같은 페이지를 쓰는 경우이다.')),
sec('11.7','저장장치 연결',452,456,
 tab(['방법','접근 형태와 특징'],[['호스트 연결','로컬 I/O 포트로 특정 장치의 논리 블록을 읽고 쓴다. USB·SATA·FC 등의 연결이 사용된다.'],['NAS','NFS·CIFS 등의 RPC로 네트워크상의 파일을 공유한다. 로컬 파일 시스템 같은 이름·접근을 제공하지만 데이터 네트워크 대역폭과 성능 비용이 있다.'],['iSCSI','IP 네트워크로 SCSI 명령과 논리 블록을 전달한다. 파일 시스템을 제공하는 NFS·CIFS와 달리 클라이언트가 raw 블록을 쓰거나 파일 시스템을 만든다.'],['클라우드 저장장치','WAN·인터넷을 거쳐 원격 데이터 센터의 저장장치에 접근하며 대체로 API를 사용한다. LAN용 NAS보다 지연·연결 장애의 가능성을 고려한다.'],['SAN','서버와 저장장치 유닛을 저장장치 프로토콜로 연결하는 사유 네트워크이다. 동적 할당·공유가 유연하고 일반 데이터 네트워크와의 경쟁을 줄인다.']]),
 p('NAS의 NFS·CIFS는 파일 공유를 위해 잠금 기능을 제공한다. SAN 스위치는 호스트의 접근을 허용·금지하고 여러 호스트에 저장장치를 배정한다. SAN은 포트가 많아 비용이 크지만 근거리 연결이므로 NAS가 더 많은 호스트를 연결할 수도 있다. 저장장치 배열은 드라이브·컨트롤러·캐시·관리 소프트웨어를 갖춘 독립 장치이며 RAID·스냅숏·복제·압축·중복 제거·암호화 등을 구현할 수 있다. SSD만 쓰거나 HDD와 조합하여 용도에 맞게 배치·캐싱할 수도 있다.')),
sec('11.8.1','중복으로 신뢰성 향상',456,458,
 p('**RAID**는 여러 드라이브를 이용하여 성능과 신뢰성을 높이는 구성이다. 원문은 I가 과거 inexpensive에서 independent로 해석되는 추세도 소개한다. 드라이브 수만 늘리고 데이터 사본은 하나만 유지하면 전체의 고장 가능성이 커진다. 중복 정보는 보통 불필요하지만 고장 시 분실 정보를 재구성하는 데 쓰인다.'),
 formula('100,000 / 100 = 1,000시간','원문의 단일 드라이브 MTBF가 100,000시간인 100개 드라이브 집합의 고장 간 평균 시간 예이다.'),
 p('**미러링**은 하나의 논리 드라이브를 두 물리 드라이브로 만들고 모든 쓰기를 양쪽에 수행한다. 하나가 고장 나면 나머지에서 읽지만, 복구 전에 두 번째도 고장 나면 데이터가 손실된다. 신뢰성은 드라이브 MTBF뿐 아니라 교체·복구의 평균 시간에도 좌우된다.'),
 formula('100,000² / (2 × 10) = 500 × 10⁶시간','드라이브 고장이 독립적이고 단일 MTBF가 100,000시간, 평균 수리 시간이 10시간이라는 원문의 가정에서 얻는 평균 데이터 분실 시간이다. 원문은 약 57,000년으로 표현한다.'),
 p('이 독립성은 현실에서 보장되지 않는다. 전력·재해·제조 결함은 두 드라이브에 함께 영향을 주고, 노후화·복구 중 부하도 실패 가능성을 바꾼다. 두 미러 블록을 동시에 쓰다가 전원이 끊기면 둘 다 불완전할 수 있다. 순서대로 쓰거나 보호된 NVRAM 쓰기 지연 캐시를 두어 완료할 수 있게 하는 대응이 제시된다.')),
sec('11.8.2','병렬성을 이용한 성능 향상',458,459,
 p('미러의 두 드라이브로 읽기 요청을 분산하면 개별 읽기의 전송률 자체와 별도로 여러 읽기 처리 능력을 높일 수 있다. **스트라이핑**은 데이터를 드라이브에 나누어 저장한다. 비트 수준 예는 바이트의 각 비트를 여러 드라이브에 나누어 같은 시간에 더 많은 데이터를 읽는 것이다. 블록 수준에서는 블록을 여러 드라이브에 순환 배치하며 이것이 일반적으로 사용된다.'),
 formula('(i mod n) + 1','원문은 n개 드라이브에서 파일의 i번째 블록을 배치하는 드라이브 번호를 이 형태로 제시한다. 원문의 인덱스 표현을 보존한다.'),
 p('병렬성의 두 목적은 여러 작은 접근의 처리량을 부하 균등화로 높이는 것과 큰 접근의 응답 시간을 줄이는 것이다. 스트라이핑 자체는 중복이 아니므로 신뢰성을 높이지 않는다.')),
sec('11.8.3','RAID 레벨과 구현',459,464,
 tab(['레벨','구성·보호','핵심 조건과 비용'],[['0','중복 없는 블록 수준 스트라이핑','전송률은 높이지만 오류 복구용 중복 정보가 없다.'],['1','미러링','높은 신뢰성과 간단한 복구 대신 드라이브 사본이 필요하다.'],['4','블록 스트라이핑과 전용 패리티 드라이브','고장 섹터를 식별할 수 있을 때 나머지 데이터와 패리티로 복구한다. 작은 쓰기는 데이터와 패리티의 읽기-수정-쓰기가 필요하다.'],['5','데이터·패리티를 모든 드라이브에 분산','RAID 4의 전용 패리티 드라이브 집중을 줄인다. 같은 블록과 그 패리티는 동일 드라이브에 두지 않는다.'],['6','P+Q의 두 중복 정보','두 드라이브 고장을 허용한다. 같은 XOR 결과를 두 번 저장하는 것만으로는 추가 보호가 되지 않는다.'],['다차원 6','논리적 행·열 방향에 RAID 6 적용','여러 위치의 중복 정보를 이용한다. 그림은 단순화를 위해 전용 패리티 드라이브로 보이지만 실제 블록은 분산된다.'],['0+1','스트라이프 집합을 다시 미러링','단일 고장으로 한 스트라이프가 사용 불가능해질 수 있다.'],['1+0','미러 쌍들을 스트라이핑','한 드라이브 고장 뒤에도 해당 미러와 다른 쌍이 계속 사용될 수 있다.']]),
 fig(c,460,'O11-F03','그림 11.15 RAID 레벨',(0.29,0.083,0.76,0.63),'P는 오류 교정 정보, C는 두 번째 사본이다. 중복 없는 스트라이핑, 미러링, 전용·분산 패리티, 이중 패리티의 차이를 보존한다.'),
 p('RAID 4의 작은 쓰기는 이전 데이터·패리티 읽기 두 번과 새 데이터·패리티 쓰기 두 번, 총 네 드라이브 접근을 요구한다. XOR 계산·기록도 비용이다. 전용 패리티 하드웨어와 NVRAM 캐시는 CPU 부담을 줄이고 전체 스트라이프가 모이면 병렬 기록하여 읽기-수정-쓰기를 줄일 수 있다. WAFL은 0으로 초기화한 드라이브를 추가해도 패리티가 바뀌지 않는 RAID 4의 확장 특성을 이용한다.'),
 fig(c,463,'O11-F04','그림 11.16 RAID 0+1과 1+0의 단일 장애',(0.21,0.076,0.76,0.515),'스트라이핑 후 미러링하는 구조와 미러링 후 스트라이핑하는 구조에서 고장 영향 범위를 비교한다.'),
 p('RAID는 커널·볼륨 관리 소프트웨어, HBA, 저장장치 배열, SAN 내부 연결 계층에서 구현할 수 있다. 위치에 따라 비용·유연성·공유 범위가 다르다. 스냅숏은 갱신 전 파일 시스템 모습이고 복제는 다른 위치에 같은 내용을 자동 기록하는 것이다. 동기 복제는 로컬·원격 기록 뒤 완료하고, 비동기 복제는 묶어서 기록하므로 빠르고 거리에 덜 제한되지만 주 사이트 고장 시 미전달 데이터가 손실될 수 있다. **hot spare**는 데이터를 담지 않고 대기하다 고장 드라이브를 자동 대체하여 복구 지연을 줄인다.')),
sec('11.8.4','RAID 레벨 선택',464,466,
 p('선택 기준에는 정상 성능뿐 아니라 고장 후 데이터를 계속 공급할 능력과 복구 시간·비용·공간 오버헤드가 포함된다. RAID 1은 복사로 복구하여 단순하고, 패리티 방식은 다른 드라이브에 접근해 재구성한다. 큰 RAID 5의 복구는 오래 걸릴 수 있다. 레벨 0은 데이터를 다시 적재할 수 있는 고성능 용도, 레벨 1은 빠른 복구, 0+1·1+0은 성능과 신뢰성이 함께 중요한 용도의 예로 제시된다.'),
 p('패리티 하나로 더 많은 데이터를 보호하면 공간 비용은 줄지만 복구 전 추가 고장에 노출될 수 있다. 드라이브 수를 늘리는 것도 전송률과 비용을 함께 바꾼다. 별도 사례인 InServ는 드라이브를 256MB chunklet으로 나누어 서로 다른 볼륨과 RAID 레벨에 쓸 수 있게 한다. 논리적으로 큰 공간을 먼저 제공하고 실제 쓰임에 따라 물리 저장장치를 할당하는 방식과 쓰기 시 복사 스냅숏도 설명된다.')),
sec('11.8.5','확장',466,466,
 p('RAID의 중복·분산 개념은 테이프와 무선 데이터 전송에도 적용된다. 여러 테이프에 스트라이핑하면 처리량을 높이고 백업 시간을 줄일 수 있다. 데이터 조각과 패리티를 함께 전송하면 일부 조각을 수신하지 못해도 다른 조각에서 복구할 수 있다.')),
sec('11.8.6','RAID의 문제점들',466,468,
 p('RAID는 물리 매체 오류를 보호하지만 모든 데이터 손상을 막지는 않는다. 잘못된 포인터, 미완료 쓰기(torn writes), 잘못된 쓰기, 컨트롤러 고장, RAID 소프트웨어 버그는 여전히 위험하다. 원문 ZFS는 데이터뿐 아니라 메타데이터도 체크섬으로 검사하며, 체크섬을 해당 블록 자체가 아니라 **그 블록을 가리키는 포인터와 함께** 둔다. 미러에 올바른 사본이 있으면 손상 블록을 갱신할 수 있다.'),
 fig(c,467,'O11-F05','그림 11.17 ZFS의 메타데이터·데이터 체크섬',(0.28,0.096,0.79,0.402),'상위 메타데이터의 포인터와 체크섬이 하위 메타데이터·데이터를 함께 검증하는 관계이다.'),
 p('별도 볼륨·파일 시스템 크기는 수요가 변할 때 부적절해질 수 있고, 볼륨을 바꿔도 파일 시스템이 확장·축소를 지원하지 않을 수 있다. ZFS는 파일 시스템 관리와 볼륨 관리를 통합하고 RAID 드라이브를 **저장장치 풀**로 묶어 여러 파일 시스템에 필요에 따라 할당·반환한다. 쿼터는 파일 시스템 크기를 제한하고 예약은 지정 크기까지 확장을 보장한다. 이 변수들은 변경 가능하다.')),
sec('11.8.7','객체 저장소',468,469,
 steps('원문의 객체 접근 순서','풀에 객체를 생성하고 객체 ID를 받는다.','필요할 때 객체 ID로 접근한다.','객체 ID로 삭제한다.'),
 p('객체 저장소는 일반 파일 시스템처럼 사용자가 디렉터리를 탐색하는 대신 프로그램이 ID로 접근하도록 설계된다. 관리 소프트웨어가 위치와 복제를 결정한다. 원문의 HDFS 예는 서로 다른 컴퓨터에 여러 사본을 두고 사본이 있는 컴퓨터에서 계산한 결과를 전송한다. 다른 컴퓨터의 데이터 접근에는 네트워크가 필요하여 고속 임의 접근보다는 대량 저장에 사용된다.'),
 p('컴퓨터와 디스크를 더해 풀을 늘리는 **수평 확장성**과 내용의 설명을 포함하는 자체 설명성이 특징이다. 원문은 콘텐츠를 기반으로 검색할 수 있어 콘텐츠 주소지정가능 저장소라고도 하며 형식이 정해지지 않은 구조화되지 않은 데이터를 저장한다고 설명한다. 이는 원문의 객체 저장소 설명 범위이다.')),
sec('11.9','요약과 원문 연습문제의 점검 범위',469,473,
 p('원문 요약은 논리 블록·연결 방식·스케줄링·오류 처리·파티션/볼륨·스왑·RAID·객체 저장소를 다시 연결한다. 장말 연습문제(인쇄532~533쪽)는 스케줄링의 적용 조건, 회전 지연, 장치 간 I/O 균형, 코드 페이지와 스왑, 안정 저장장치, 전송 크기와 유효 전송률, RAID 읽기, HDD/NVM 선택을 점검한다. 원문에 제시되지 않은 풀이·계산 결과를 추가하지 않는다. 추가 자료와 참고문헌은 존재를 확인했으며 외부 내용을 요약에 보충하지 않았다.'))]
c['key_points']=['HDD는 탐색·회전 지연이 중요하고 NVM은 삭제 단위·마모·가비지 수집·쓰기 증폭이 중요하다.','FCFS의 공정성, SCAN의 양방향 처리, C-SCAN의 한 방향 처리와 귀환을 구분한다.','오류 감지와 수정, 논리 주소와 실제 위치, 파티션·볼륨·파일 시스템은 각각 다른 역할이다.','미러링은 중복을, 스트라이핑은 병렬성을 제공한다. RAID 레벨은 성능·공간 비용·복구 능력의 조합이다.','RAID만으로 논리적 손상·소프트웨어 오류까지 모두 보호할 수는 없다.']
c['review']=['물리 구조 → 논리 블록 → 요청 큐 → 매핑·복구라는 연결을 먼저 떠올린다.','스왑 파일과 raw 파티션은 관리 편의와 성능·크기 변경의 조건이 다르다.','NAS의 파일, iSCSI의 논리 블록, SAN의 저장장치 연결, 클라우드의 API 접근을 구별한다.','ZFS는 포인터에 둔 체크섬과 공유 풀을 통해 무결성·크기 관리 문제를 다룬다.']
c['index_terms']=[{'term':t,'section':s} for t,s in [('FTL','11.1.2'),('쓰기 증폭','11.3'),('FCFS','11.2.1'),('SCAN','11.2.2'),('C-SCAN','11.2.3'),('ECC','11.4'),('스왑 맵','11.6'),('RAID','11.8.3'),('ZFS','11.8.6'),('객체 저장소','11.8.7')]]
c['verification']['visually_checked_pdf_pages'] += [458]
c['verification']['notes']=['PDF430~473 전 페이지 OCR 원문을 읽고 본문·그림 레이블·장말 문제·추가 자료를 분류했다.','FCFS 큐·시작53·이동640과 C-SCAN 방향을 PDF440·442 이미지로 대조했다. RAID 도표·0+1/1+0·ZFS 체크섬은 원문 이미지를 크롭해 보존했다.','미러 MTBF의 제곱·지수·가정은 PDF458 이미지로 대조했다. 원문의 과거 버전 예를 현재 사실로 갱신하지 않았다.']
finish(c)

c=chapter(15,'파일 시스템 내부구조',591,614,
 ['여러 파일 시스템을 하나의 이름 공간에 연결하는 마운트와 VFS를 정리한다. 다중 사용자 공유·원격 고장·일관성 의미를 구분하고 원문의 NFS 버전 3 중심 설명으로 마운트·원격 연산·경로 변환·캐싱을 따라간다.'],
 ['파일 시스템의 다양성 → 마운트·부팅 → 다중 사용자 공유 → VFS → 원격 접근·인증·고장 → 일관성 의미 → NFS의 프로토콜과 캐시'])
c['sections']=[
sec('15.1','파일 시스템',591,593,
 p('저장장치는 파티션을, 파티션·장치들의 볼륨은 파일 시스템을 보유한다. 볼륨 관리자는 여러 파티션에 걸친 볼륨을 제공할 수 있다. 한 컴퓨터에는 여러 종류의 파일 시스템이 함께 존재한다. 범용 저장뿐 아니라 메인 메모리의 임시 tmpfs, 커널 심볼을 노출하는 objfs, 프로세스 정보를 제공하는 procfs, 다른 파일 시스템을 다시 보이게 하는 lofs 등 특수 목적도 있다. 일부 가상 파일 시스템은 실제 디스크 파일이 아니라 커널 인터페이스를 파일처럼 보이게 한다.')),
sec('15.2','파일 시스템 마운팅',593,595,
 steps('원문의 마운트 절차','장치 이름과 기존 이름 구조에 부착할 마운트 포인트를 지정한다. 시스템에 따라 파일 시스템 유형도 지정하거나 구조를 검사하여 알아낸다.','장치 드라이버를 통해 디렉터리를 읽어 유효한 파일 시스템 형식인지 확인한다.','지정 지점에 마운트되었다는 정보를 기록한다. 경로 순회는 그 지점에서 알맞은 파일 시스템으로 넘어간다.'),
 p('마운트 전에는 새 볼륨의 파일을 기존 이름 공간에서 사용할 수 없다. 원문의 /users 예는 기존 하부 구조 대신 새 볼륨의 하부 트리가 보이며 언마운트하면 원래 구조가 다시 보이는 것을 설명한다. 비어 있지 않은 디렉터리의 마운트를 금지할지, 원래 내용을 가릴지, 같은 파일 시스템을 여러 곳에 붙일지는 시스템의 의미와 정책에 따른다.'),
 fig(c,594,'O15-F01','그림 15.4 /users에 마운트 된 볼륨',(0.405,0.695,0.72,0.943),'기존 이름 공간의 /users가 새 볼륨의 하위 파일·디렉터리를 제공하는 마운트 결과이다.'),
 p('원문은 macOS의 자동 발견·마운트, Windows의 드라이브 문자와 디렉터리 마운트, UNIX의 구성 파일과 명시적 명령을 비교한다. 자동 여부와 이름 표시 방식은 운영체제에 따라 달라진다.')),
sec('15.3','파티션과 마운팅',595,596,
 p('파티션은 파일 시스템을 가진 **cooked** 형태 또는 파일 시스템 없이 고유 형식을 사용하는 **raw** 형태일 수 있다. 스왑·일부 데이터베이스·RAID 관리 정보가 raw 사용의 예이다. 부팅할 때는 아직 일반 파일 시스템 코드가 적재되지 않았으므로 부트 정보가 별도 형식이어야 하며 부트스트랩 로더가 커널을 찾아 적재할 만큼 파일 시스템을 이해해야 한다.'),
 p('여러 파티션에 여러 운영체제를 둘 수 있어 부트 로더가 어느 것을 시작할지 선택한다. 로더가 이해하지 못하는 파일 시스템의 운영체제는 시작할 수 없어 루트 파일 시스템 선택에 제약이 된다. 루트 파티션은 부팅 때 마운트하고 다른 파티션은 자동 또는 나중에 수동으로 마운트한다.'),
 p('마운트 테이블은 유형과 장치를 연결한다. 원문의 Windows 예는 드라이브 문자에 파일 시스템 포인터를 연관시킨다. UNIX는 마운트 포인트 디렉터리의 메모리 inode에 플래그와 마운트 테이블 포인터를 두고 그 항목이 해당 파일 시스템의 슈퍼블록을 가리킨다. 경로 순회는 이 정보를 통해 파일 시스템을 전환한다.')),
sec('15.4.1','파일 공유와 다수의 사용자',596,597,
 p('공유는 공동 작업을 돕지만 이름·보호·상충되는 쓰기를 조정해야 한다. 파일·디렉터리의 소유자와 그룹 ID를 저장하고 요청한 사용자의 ID·그룹 ID와 비교하여 연산을 허용·거부한다. 소유자는 속성·허가를 제어하며 그룹은 공유 사용자 집합을 정한다.'),
 p('로컬에서 여러 파일 시스템을 마운트할 때도 ID와 허가를 검사한다. 이동식 장치를 다른 컴퓨터로 가져가면 ID가 다른 사용자를 가리킬 수 있으므로 ID가 일치하거나 소유권이 적절히 재설정되도록 해야 한다. 원격 시스템에서도 같은 신원 대응 문제가 확장된다.')),
sec('15.5','가상 파일 시스템',598,600,
 p('**VFS(virtual file system)**는 기본 시스템 콜을 구체적 파일 시스템 구현에서 분리한다. 위에는 open·read·write·close와 디스크립터의 인터페이스, 가운데는 VFS, 아래에는 유형별 로컬 파일 시스템 또는 원격 프로토콜 구현을 둔다. 서로 다른 구현이 함께 존재하면서 사용자는 통합 이름 공간을 탐색할 수 있다.'),
 fig(c,599,'O15-F02','그림 15.5 가상 파일 시스템의 개략적 모습',(0.22,0.106,0.85,0.477),'동일한 파일 인터페이스가 VFS를 거쳐 여러 로컬 파일 시스템과 원격 파일 시스템에 연결된다.'),
 p('VFS의 **vnode**는 활성 파일·디렉터리를 나타내며 원문은 개별 파일 시스템 안에서 유일한 inode와 네트워크에서 파일을 구별해야 하는 vnode의 역할을 구분한다. 로컬 요청은 해당 파일 시스템 함수로, 원격 요청은 NFS 등의 프로토콜로 보낸다. 객체의 연산 함수 테이블이 실제 구현의 주소를 담으므로 상위 층은 적절한 함수를 선택한다.'),
 tab(['Linux VFS 객체','원문의 표현 대상'],[['Inode object','각 파일'],['File object','열린 파일'],['Superblock object','전체 파일 시스템'],['Dentry object','각 디렉터리 항목']]),
 p('파일 객체의 함수 집합에는 open·close·read·write·mmap 등이 있다. VFS는 파일의 구체적 종류마다 처리 코드를 직접 중복하기보다 해당 객체의 테이블에서 연산을 찾아 호출한다.')),
sec('15.6','원격 파일 시스템',600,600,
 p('원격 공유의 방법으로 사용자가 ftp 등으로 직접 전송하는 방식, 원격 디렉터리를 통합하여 접근하는 **DFS(분산 파일 시스템)**, 웹·클라우드를 통한 접근이 소개된다. 익명 전송은 서버 계정 없이 가능할 수 있으나 DFS는 클라이언트와 서버의 더 긴밀한 통합을 요구하므로 복잡성이 커진다.')),
sec('15.6.1','클라이언트 서버 모델',600,601,
 p('파일을 가진 컴퓨터는 서버, 접근하려는 컴퓨터는 클라이언트이다. 서버는 제공하는 볼륨·디렉터리와 허용 클라이언트를 명시하며 다수 서버·다수 클라이언트 관계가 가능하다. 한 컴퓨터가 동시에 양쪽 역할을 할 수 있다.'),
 p('네트워크 이름·IP만의 식별은 스푸핑에 취약하다. 암호화된 키를 쓰는 인증도 알고리즘 호환과 안전한 키 교환이 필요하다. 원문의 UNIX/NFS 사례에서는 클라이언트·서버의 사용자 ID가 일치해야 파일 접근 검사도 올바르다. 같은 사용자가 양쪽에서 서로 다른 ID를 가지면 서버가 다른 사람의 권한을 검사할 수 있다. 마운트 뒤 파일 연산은 사용자 신원과 함께 프로토콜로 전달되고 서버가 권한을 판단한다.')),
sec('15.6.2','분산 정보 시스템',601,602,
 p('분산 정보·네이밍 서비스는 원격 컴퓨팅에 필요한 정보를 통일된 방식으로 제공한다. DNS는 호스트 이름을 네트워크 주소로 변환한다. 사용자 이름·암호·UID·GID·프린터 등의 정보도 중앙에서 관리할 수 있다. 원문의 NIS는 정보 집중을 제공하지만 인증의 안전성에 문제가 있고 NIS+는 더 안전하되 복잡한 사례이다.'),
 p('CIFS의 네트워크 로그인과 Active Directory, Kerberos 방식 인증, LDAP가 원문의 다른 사례이다. 통일된 사용자·자원 이름 공간은 시스템마다 흩어진 정보를 합쳐 관리 부담을 줄이고 한 번의 인증으로 조직 자원에 접근하는 단일 사인온을 가능하게 한다. 이 설명은 원문의 서비스 관계에 한정하며 새로운 구성 절차를 추가하지 않는다.')),
sec('15.6.3','고장 모드',602,603,
 p('로컬 시스템도 매체·컨트롤러·메타데이터·케이블·관리 실수로 실패할 수 있다. 원격 시스템은 여기에 네트워크 고장·잘못된 구성·서버 중단·분할 등이 더해진다. 서버를 잃었을 때 요청을 종료할지 재개까지 미룰지는 프로토콜의 오류 의미이다. 즉시 종료하면 데이터 손실이 생길 수 있어 많은 DFS는 기다리거나 연기하는 방식을 제공한다.'),
 p('상태성 방식은 열린 파일·활동을 양쪽이 기억하여 복구에 이용한다. 원문의 **NFS 버전 3** 설명은 각 요청에 필요한 정보를 담는 무상태 방식을 채택하여 구현과 재시작을 단순하게 하지만 신원·거짓 요청의 보안 문제가 남는다고 설명한다. 버전 4는 보안·성능·기능 개선을 위해 상태를 도입한 것으로 소개된다. 뒤의 상세 NFS 절 역시 책이 명시한 버전 3 중심의 범위를 유지한다.')),
sec('15.7','일관성의 의미',604,604,
 p('**일관성 의미**는 공유 파일의 한 사용자 변경이 다른 사용자에게 언제 보이는지 규정한다. 파일 시스템 코드로 구현되며 프로세스 동기화와 관련된다. 그러나 디스크·네트워크의 지연 때문에 복잡한 원자 연산을 모두 제공하면 성능 비용이 크다. 원문의 비교는 open과 close 사이의 접근을 하나의 **파일 세션**으로 가정한다.')),
sec('15.7.1','UNIX의 의미',604,604,
 p('열린 파일에 대한 쓰기는 같은 파일을 연 다른 사용자에게 즉시 보일 수 있다. 현재 위치 포인터를 공유하는 모드에서는 한 사용자의 위치 전진이 모든 공유자에 영향을 준다. 파일은 접근이 서로 엇갈려 적용되는 단일 물리 이미지를 가지며 이 배타적 자원에 대한 경쟁은 대기를 낳을 수 있다.')),
sec('15.7.2','세션 의미',604,605,
 p('원문의 Andrew/OpenAFS **세션 의미**에서는 한 사용자의 쓰기가 동시에 열어 둔 다른 사용자에게 즉시 보이지 않는다. 닫은 뒤에 시작되는 세션에서 변경이 보이고 이미 열린 인스턴스에는 반영되지 않는다. 한 파일에 일시적으로 서로 다른 이미지가 존재할 수 있어 여러 사용자가 각 이미지에서 병행하여 읽고 쓸 수 있다.')),
sec('15.7.3','불변 공유 파일의 의미',605,605,
 p('공유된다고 선언한 파일은 더 이상 변경하지 못한다. 파일 이름도 재사용하지 않고 내용도 바꾸지 않아 이름이 고정된 내용을 가리킨다. 공유 규칙이 읽기 전용으로 명확하여 분산 환경에서 구현이 단순하다.')),
sec('15.8.1','NFS 개요',605,607,
 p('**NFS**는 원격 파일 접근의 소프트웨어 구현과 명세를 뜻한다. 원문은 Solaris 구현의 예와 일반 명세 설명을 함께 사용하며 **버전 3을 중심으로** 다룬다고 명시한다. 책의 “최신 버전”·배포 빈도 설명을 현재 상황으로 갱신하지 않는다. 독립된 시스템들이 클라이언트·서버 관계로 투명하게 파일을 공유하는 것이 목표이며 서버 고장은 관련 클라이언트에 영향을 준다.'),
 p('마운트 명령에는 원격 호스트·디렉터리를 명시해야 하지만 완료 뒤에는 로컬 하부 트리처럼 투명하게 접근한다. 클라이언트의 기존 마운트 포인트 내용은 가려진다. 일부 구현은 원격 마운트 안에 다른 시스템을 다시 마운트하는 연속 마운트를 허용한다. 그러나 서버가 이미 마운트한 다른 원격 파일 시스템까지 자동으로 보이는 **이행성은 없다**. 각 기계는 자신이 수행한 마운트에 의해서만 영향을 받는다.'),
 fig(c,607,'O15-F03','그림 15.7 NFS에서의 마운팅',(0.28,0.10,0.725,0.377),'로컬 /usr/local에 원격 하위 트리를 마운트한 상태와 그 안에 다시 명시적으로 연속 마운트한 상태를 비교한다.'),
 p('서로 다른 하드웨어·운영체제·네트워크를 지원하기 위해 RPC와 **XDR(외부 자료 표현)**을 이용한다. 서비스는 초기 연결의 마운트 프로토콜과 실제 원격 연산의 NFS 프로토콜로 나뉜다. 공유 홈 디렉터리를 여러 기계에서 마운트하면 사용자 이동성도 제공할 수 있다.')),
sec('15.8.2','마운트 프로토콜',608,608,
 steps('NFS 마운트','클라이언트가 서버 이름과 원격 디렉터리를 지정한 마운트 요구를 RPC로 보낸다.','서버는 수출 리스트의 디렉터리·허가된 기계·접근 권리를 확인한다.','허용하면 파일 시스템 식별자와 디렉터리 inode 번호 등 접근에 필요한 정보를 담은 파일 핸들을 반환한다.','클라이언트는 이 핸들을 이후 원격 파일 접근에 사용한다.'),
 p('서버는 관리용 클라이언트·마운트 목록도 유지할 수 있으나 이는 실제 파일 연산의 정확성을 위한 상태와 다르다. 마운트 구성은 부팅 때 정할 수 있고 변경도 가능하며 언마운트·수출 리스트 조회 절차도 제공된다.')),
sec('15.8.3','NFS 프로토콜',608,610,
 p('NFS 프로토콜은 디렉터리 검색·항목 읽기·링크/디렉터리 조작·속성 접근·파일 읽기/쓰기의 RPC를 제공한다. 원문이 설명하는 무상태 서비스에는 **open·close가 의도적으로 없다**. 각 요청이 고유 파일 식별자와 절대 오프셋 등 필요한 매개변수를 모두 가져야 한다. 재시도에서 같은 연산을 여러 번 적용해도 한 번 적용한 결과와 같도록 멱등성을 고려하고 일련번호로 중복·누락을 구별한다.'),
 p('마운트의 관리 목록은 크래시 뒤 복원하지 않아도 정확한 연산이 가능하므로 무상태 원칙과 모순되는 필수 상태로 보지 않는다. 원문은 클라이언트에 결과를 돌려주기 전에 서버의 수정 데이터·간접/상태 블록이 안전한 저장장치에 기록되어야 한다고 설명한다. 동기 기록의 비용을 줄이기 위해 배터리로 보호된 비휘발성 캐시가 완료를 먼저 보장하고 나중에 디스크에 기록할 수 있다.'),
 p('**하나의 NFS 쓰기 RPC**는 다른 쓰기와 섞이지 않지만 사용자 write 시스템 콜은 여러 RPC로 나뉠 수 있다. 따라서 전체 시스템 콜의 데이터가 다른 사용자의 쓰기와 섞일 가능성이 남는다. 원문은 별도의 락 서비스·협조적 접근이 필요하다고 설명한다. 원문의 전송 크기와 프로토콜 조건은 해당 설명 범위의 예이며 현재 네트워크의 일반 제한으로 확대하지 않는다.'),
 steps('VFS를 통한 원격 연산','클라이언트의 일반 시스템 콜을 vnode에 대한 VFS 연산으로 변환한다.','VFS가 원격 파일임을 확인해 NFS 프로시저를 호출한다.','RPC/XDR로 서버의 NFS 서비스에 전송한다.','서버 VFS가 로컬 파일 시스템 연산으로 처리하고 같은 경로를 되돌아 결과를 보낸다.'),
 fig(c,610,'O15-F04','그림 15.8 NFS 구조의 개략도',(0.18,0.579,0.91,0.943),'클라이언트·서버 양쪽 VFS와 로컬 파일 시스템, NFS, RPC/XDR의 호출 연결을 보존한다.')),
sec('15.8.4','경로 이름 변환',611,611,
 p('경로를 구성요소 이름으로 나누고 각 이름과 디렉터리 vnode 쌍에 대해 lookup한다. 마운트 포인트를 넘은 뒤의 각 구성요소는 별도 서버 RPC를 요구할 수 있다. 경로 전체를 한꺼번에 서버에 주면 빠를 수 있지만 클라이언트마다 다른 마운트 이름 공간과 중간의 추가 마운트를 무상태 서버가 알지 못한다는 제약이 있다.'),
 p('클라이언트의 디렉터리 이름 조회 캐시는 공통 접두어를 가진 경로의 반복 참조를 빠르게 한다. 반환된 속성이 캐시된 vnode와 맞지 않으면 캐시를 버린다. 클라이언트가 명시적으로 연속 마운트한 경로는 여러 서버를 지날 수 있지만 서버 자체의 다른 마운트를 자동으로 따라가는 것은 아니다.')),
sec('15.8.5','원격 연산',611,612,
 p('개념상 파일 연산과 RPC가 대응하지만 실제로는 파일 블록·속성을 지역에 캐시하여 여러 연산이 RPC 없이 처리될 수 있다. 원문은 열린 시점에 속성의 최신 여부를 서버에 확인하고, 속성이 최신일 때만 관련 블록 캐시를 쓰며, 속성 캐시는 일정 시간 뒤 버린다고 설명한다. 미리 읽기와 지연 쓰기를 함께 사용하되 서버 기록 완료를 확인하기 전까지 지연 쓰기 블록을 해제하지 않는다.'),
 p('캐시와 지연 쓰기로 인해 다른 기계의 새 파일·수정이 곧바로 보이지 않을 수 있다. 이미 열린 파일에서 보이는 내용과 새 open에서 보이는 내용도 구별해야 한다. 따라서 원문의 NFS는 엄격한 UNIX 의미도 Andrew의 세션 의미도 그대로 제공하지 않는다고 결론짓는다. 성능을 위한 조정이 일관성 의미에 미치는 영향이 핵심이다.')),
sec('15.9','요약과 원문 연습문제의 점검 범위',612,614,
 p('다양한 파일 시스템은 마운트와 VFS를 통해 통합되고, 파일 공유에는 신원·권한·일관성 의미가 필요하다. 원격 공유는 통신·인증·고장·경로 변환과 캐시 일관성까지 고려한다. 장말 문제는 VFS의 역할, 여러 파일 시스템 유형의 필요, procfs, 이름 공간 통합과 별도 표시, ftp와 NFS의 차이를 점검한다. 추가 자료·참고문헌은 확인했지만 원문에 없는 실습 명령이나 풀이를 작성하지 않았다.'))]
c['comparisons']=[{'title':'원문의 파일 공유 일관성 의미','source':src(604,605),'headers':['모델','변경이 보이는 시점·조건'],'rows':[['UNIX','같이 열린 파일의 다른 사용자에게 즉시 보일 수 있다. 단일 이미지이다.'],['세션','닫은 이후 새로 시작한 세션에서 보이며 기존 열린 인스턴스에는 반영되지 않는다.'],['불변 공유','공유 선언 후 내용 변경·이름 재사용이 없다.']]}]
c['key_points']=['마운트는 파일 시스템을 이름 공간에 부착하고 VFS는 서로 다른 구현의 연산을 공통 인터페이스로 전달한다.','파일 소유자·그룹의 ID는 다른 장치·원격 기계에서도 올바르게 대응해야 한다.','파일 세션은 open부터 close까지이고 일관성 의미는 변경의 관찰 시점을 정한다.','원문의 NFS 상세 설명은 버전 3 중심이다. 무상태 요청과 관리용 마운트 목록의 성격을 구분한다.','NFS의 단일 RPC 원자성과 응용 write 전체, 캐시 성능과 즉시 가시성을 혼동하지 않는다.']
c['review']=['부팅·파티션·볼륨·마운트는 커널을 찾고 여러 저장장치를 하나의 경로로 제공하는 연결이다.','VFS는 함수 테이블로 로컬·원격 구현을 선택하고 NFS는 RPC/XDR를 통해 서버 VFS로 이어진다.','무상태성은 요청 자체의 완전한 정보를 요구하며 캐싱·지연 쓰기는 일관성 의미를 바꾼다.']
c['index_terms']=[{'term':t,'section':s} for t,s in [('마운트','15.2'),('raw 파티션','15.3'),('VFS','15.5'),('vnode','15.5'),('분산 정보 시스템','15.6.2'),('세션 의미','15.7.2'),('NFS','15.8.1'),('XDR','15.8.1'),('무상태','15.8.3'),('경로 이름 변환','15.8.4')]]
c['verification']['notes']=['PDF591~614 전 페이지를 읽고 본문·장말 문제·참고문헌을 검토했다. PDF615는 Part7 도입이므로 본 장에 포함하지 않았다.','VFS·로컬마운트·NFS연속마운트·RPC구조는PDF594·599·607·610원문이미지직접대조후크롭했다.','버전3 중심의 무상태성·동기 기록·캐시 의미를 원문 범위로 제한하고 현재 표준·외부 지식으로 갱신하지 않았다.']
finish(c)

c=chapter(14,'파일 시스템 구현',554,590,
 ['파일의 논리적 인터페이스를 실제 저장 블록으로 구현하는 자료구조와 알고리즘을 살펴본다. 디렉터리·블록 할당·가용 공간·캐시의 절충을 정리하고 크래시 복구와 WAFL의 스냅숏을 연결한다.'],
 ['계층별 역할 → 장치·메모리 자료구조와 open/close → 디렉터리 → 연속/연결/색인 할당 → 가용 공간 → 효율·캐시 → 일관성·로그·백업 → WAFL'])
c['sections']=[
sec('14.1','파일 시스템 구조',555,557,
 p('파일 시스템의 두 설계 문제는 사용자에게 보이는 파일·속성·연산을 정의하는 일과 이를 실제 보조저장장치에 대응시키는 알고리즘·자료구조를 만드는 일이다. 원문은 재기록·직접 접근이 가능한 HDD와 덮어쓰기 특성이 다른 NVM을 구별하며, 효율을 위해 블록 단위로 I/O한다.'),
 tab(['층','역할'],[['논리 파일 시스템','디렉터리·메타데이터·보호·FCB를 관리하고 이름을 하위 계층의 정보로 변환한다.'],['파일-구성 모듈','파일의 논리 블록과 실제 공간의 관계를 알고 가용 공간 관리자를 포함한다.'],['기본 파일 시스템','LBA 기반의 블록 읽기·쓰기, I/O 스케줄링, 버퍼·캐시를 관리한다.'],['I/O 제어','드라이버·인터럽트 핸들러가 일반 명령을 특정 하드웨어 명령으로 바꾸고 전송한다.']]),
 p('**메타데이터**는 파일 내용 자체를 제외한 파일 시스템 구조이다. **FCB**는 소유·권한·내용의 위치 같은 파일 정보를 담고 UNIX에서는 inode가 그 역할을 한다. 계층화는 코드 중복을 줄여 여러 파일 시스템이 하위 코드를 공유하게 하지만 계층 통과 비용을 늘릴 수 있다. 파일 시스템마다 기능·성능·신뢰성·목적이 달라 여러 구현이 존재하고 FUSE는 사용자 수준 구현의 유연성을 제공하는 사례이다.')),
sec('14.2.1','파일 시스템 구현 개요',557,559,
 tab(['장치상의 구조','담는 정보'],[['부트 제어 블록','해당 파티션에서 운영체제를 부팅하는 정보'],['볼륨 제어 블록','전체·가용 블록 수, 블록 크기, 가용 공간과 FCB의 수·포인터'],['디렉터리','이름과 파일 식별·제어 정보의 연결'],['파일별 FCB','고유 식별자와 자세한 파일 정보']]),
 p('메모리에는 마운트된 파티션 정보, 최근 디렉터리 정보, FCB 사본을 담은 범 시스템 열린 파일 테이블, 이를 가리키는 프로세스별 열린 파일 테이블, 전송 중 블록 버퍼를 둔다. 마운트 때 적재하고 동작 중 갱신하며 해제 때 제거한다. 파일 생성은 새 FCB를 할당하고 디렉터리에 이름·FCB 연결을 추가한 뒤 기록하는 작업이다. 디렉터리를 특별 파일로 구현하는지 별개 객체로 보는지는 시스템에 따라 다르다.')),
sec('14.2.2','사용법',559,560,
 steps('open부터 close까지','open이 먼저 범 시스템 테이블을 확인한다. 이미 열려 있으면 그 항목을 가리키는 프로세스별 항목을 만든다.','처음 열 때는 디렉터리에서 찾아 FCB를 범 시스템 테이블에 복사한다. 프로세스별 항목에는 현재 위치와 접근 모드 등을 둔다.','프로세스는 반환된 파일 디스크립터(UNIX) 또는 핸들(Windows)로 후속 연산을 한다. 매번 파일 이름을 다시 검색하지 않는다.','close는 프로세스별 항목을 없애고 열린 계수를 줄인다. 마지막 사용자가 닫으면 갱신 정보를 디스크에 반영하고 범 시스템 항목을 회수한다.'),
 p('이름·디렉터리·FCB를 캐싱하면 실제 데이터 외의 파일 정보를 메모리에서 해결하여 저장장치 접근을 줄일 수 있다. 테이블은 파일별 공통 정보와 프로세스별 사용 상태를 구별하는 구조이다.')),
sec('14.3.1','선형 리스트',561,561,
 p('파일 이름과 데이터 블록 포인터의 **선형 리스트**는 구현이 쉽지만 검색 시간이 길다. 생성은 같은 이름이 없는지 검색한 뒤 추가하고, 삭제는 공간을 돌려주고 항목을 비워 재사용한다. 사용 비트·특별 이름·잘못된 inode 번호 표시, 마지막 항목 복사, 연결 리스트 등으로 빈 항목을 관리할 수 있다.'),
 p('정렬하면 이진 검색과 정렬된 목록 출력이 쉬워지지만 삽입·삭제 때 정보 이동이 필요하다. 트리 구조나 최근 디렉터리 캐시가 보완할 수 있다. 디렉터리 검색은 빈번하므로 단순한 구현의 속도 비용이 중요하다.')),
sec('14.3.2','해시 테이블',561,562,
 p('**해시 테이블**은 파일 이름을 값으로 바꾸어 항목 위치를 빠르게 찾는다. 충돌 처리가 필요하며 크기가 고정되면 확장 때 함수와 기존 항목을 재구성해야 할 수 있다. 원문의 64항목에서 65번째 항목을 추가하는 예는 더 큰 테이블과 재해싱의 필요를 보여준다. 체인 오버플로 방식은 각 해시 항목의 연결 리스트에 충돌 항목을 넣어 확장하지만 그 리스트를 탐색하는 비용이 있다.')),
sec('14.4.1','연속 할당',562,564,
 p('**연속 할당**은 파일이 연속한 블록을 차지하게 하고 디렉터리에 시작 블록과 길이를 기록한다. 시작이 b이고 길이가 n이면 b부터 b+n−1까지이며 i번째 블록은 b+i이다. 순차·직접 접근이 모두 쉽고 HDD의 헤드 이동을 줄일 수 있다. 이 이익은 가까운 논리 주소가 물리적으로도 가깝다는 전제를 가진다.'),
 p('가용 연속 영역 선택은 동적 공간 할당 문제이다. 최초 적합·최적 적합 등을 사용할 수 있지만 **외부 단편화**로 전체 빈 공간은 충분해도 요구 크기의 한 덩어리가 없을 수 있다. 다른 장치로 복사했다 돌아오거나 밀집화하면 개선되지만 시간·비용·정상 운영 중 성능 저하가 크다.'),
 p('파일 최종 크기도 예측하기 어렵다. 작게 예약하면 인접 공간이 없어 확장할 수 없고, 종료 후 다시 실행하거나 더 큰 공간에 전체를 복사해야 한다. 지나치게 선할당하면 오랫동안 사용하지 않는 공간이 낭비된다. **익스텐트**는 초기의 연속 영역이 부족할 때 연속 블록 묶음을 추가하여 위치·길이·다음 묶음 포인터를 기록하는 절충이다.')),
sec('14.4.2','연결 할당과 FAT',564,567,
 p('**연결 할당**은 파일을 장치에 흩어질 수 있는 블록의 연결 리스트로 저장한다. 각 블록이 다음 블록을 가리키고 디렉터리는 시작·끝을 기억한다. 파일 크기를 미리 정하지 않고 가용 블록을 계속 붙일 수 있어 외부 단편화·밀집화 문제를 피한다. 반면 직접 접근은 앞의 링크를 따라가야 하므로 비효율적이다.'),
 p('포인터가 데이터 공간을 차지한다. 원문 예는 512바이트 블록의 4바이트 포인터로 508바이트만 데이터를 담는 경우이다. 여러 블록을 **클러스터**로 묶으면 포인터·할당 관리와 HDD 탐색을 줄이지만 내부 단편화와 작은 임의 요청의 전송량은 늘어난다. 링크 하나의 손상은 후속 데이터 접근을 잃게 할 수 있고 이중 링크·추가 식별 정보는 더 많은 비용을 요구한다.'),
 p('**FAT(파일 할당 테이블)**는 링크들을 파티션의 별도 연속 테이블로 모은 변형이다. 디렉터리의 시작 블록을 인덱스로 FAT를 찾으면 다음 블록 번호를 얻고 특수 값으로 끝을 표시한다. 원문 예의 사슬은 217→618→339이다. FAT가 메모리에 캐시되지 않으면 테이블과 데이터 위치 사이의 왕복 탐색이 늘 수 있다.'),
 fig(c,566,'O14-F01','그림 14.6 파일 할당 테이블(FAT)',(0.25,0.586,0.82,0.947),'디렉터리의 시작 블록 217에서 FAT 항목을 따라 618·339로 연결되는 구조를 보존한다.')),
sec('14.4.3','색인 할당',567,569,
 p('**색인 할당**은 파일마다 블록 주소 배열인 색인 블록을 두고 i번째 항목이 i번째 데이터 블록을 가리키게 한다. 디렉터리는 색인 블록의 주소를 갖는다. 새 파일은 포인터를 null로 시작하고 실제 블록을 쓸 때 주소를 넣는다. 외부 단편화 없이 직접 접근을 지원하지만 작은 파일에도 색인 블록 전체가 필요하여 포인터 오버헤드가 크다. 색인을 작게 하면 큰 파일을 표현할 별도 방법이 필요하다.'),
 tab(['확장 방법','구조와 조건'],[['연결 기법','색인 블록의 마지막 포인터로 다음 색인 블록을 연결한다.'],['다중 수준 색인','상위 색인이 하위 색인 블록을 가리키고 최하위 색인이 데이터를 가리킨다. 필요하면 수준을 더한다.'],['결합 기법','inode 안의 직접 포인터와 단일·이중·삼중 간접 포인터를 함께 사용한다. 작은 파일은 추가 색인을 피하고 큰 파일은 간접 수준을 쓴다.']]),
 p('원문 다중 색인 예는 4,096바이트 블록에 4바이트 포인터 1,024개를 넣고, 두 수준으로 1,048,576 데이터 블록, 4GB 파일을 표현한다. 결합 예의 15개 포인터 중 12개는 직접 블록이고 나머지 3개가 단일·이중·삼중 간접 블록이다. 4KB 블록이면 처음 48KB는 직접 포인터로 접근한다. 색인을 캐시해도 데이터 자체는 볼륨 전역에 흩어질 수 있다.'),
 fig(c,569,'O14-F02','그림 14.8 UNIX의 inode',(0.27,0.10,0.83,0.483),'직접·단일 간접·이중 간접·삼중 간접 블록의 포인터 수준과 데이터 도달 관계를 보여준다.')),
sec('14.4.4','할당 방법의 성능',569,570,
 tab(['방법','접근과 절충'],[['연속','시작과 변위로 즉시 블록을 결정하지만 공간 확보·성장·외부 단편화가 문제이다.'],['연결','다음 블록의 순차 접근은 쉽지만 i번째 직접 접근에 여러 링크 읽기가 필요하다.'],['색인','색인의 메모리 상주 여부·구조·파일 크기·목표 위치에 따라 추가 I/O가 달라진다.']]),
 p('시스템의 주 사용 패턴이 선택 기준이다. 순차·직접 파일을 다른 방식으로 저장하거나 작은 파일은 연속, 커지면 색인으로 전환하는 결합도 있다. HDD에서는 탐색을 줄이기 위한 추가 CPU 연산이 타당할 수 있으나, 헤드가 없는 NVM에 같은 최적화를 그대로 쓰면 불필요한 비용이 된다. NVM은 명령 수와 접근 경로를 줄이는 최적화가 필요하다는 것이 원문의 설명이다.')),
sec('14.5.1','비트 벡터',571,572,
 p('가용 공간 관리는 할당 시 빈 블록을 제거하고 삭제 시 되돌려 받는 역할이다. 목록이라는 이름이어도 반드시 연결 리스트일 필요는 없다. **비트맵**은 블록당 한 비트를 사용한다. 이 원문의 표기에서는 **1이 가용, 0이 할당**이다. 워드를 검사하여 처음 0이 아닌 워드와 그 안의 첫 1을 찾으면 첫 가용 블록을 구할 수 있다. 연속 가용 블록 탐색도 쉽다.'),
 formula('(워드의 비트 수) × (값이 0인 워드의 수) + 첫 번째 1비트의 변위','원문이 제시한 첫 가용 블록 번호의 계산식이다. 앞의 워드는 모두 할당 비트 0으로만 구성되어 있다는 검색 절차의 전제를 갖는다.'),
 p('하드웨어 비트 연산은 효율적이지만 큰 비트맵을 메모리에 두기 어렵다. 원문은 4KB 블록의 1TB 디스크에 32MB 비트맵이 필요하다고 설명한다. 블록·클러스터가 커지면 관리 비트 수는 줄지만 공간 할당의 단위도 커진다. 복구를 위해 장치상의 기록도 유지해야 한다.')),
sec('14.5.2','연결 리스트',572,572,
 p('모든 가용 블록을 다음 가용 블록의 포인터로 연결하고 첫 포인터를 정해진 위치와 메모리에 둔다. 전체 순회는 디스크 접근이 많아 비싸지만 보통 할당에는 첫 가용 블록만 필요하다. FAT는 할당 사슬과 가용 블록의 관리를 같은 테이블에서 처리하여 별도 구조를 줄일 수 있다.')),
sec('14.5.3','그룹핑',573,573,
 p('첫 가용 블록에 n개의 주소를 넣고 처음 n−1개는 실제 빈 블록, 마지막은 같은 형식의 다음 주소 묶음을 가진 블록을 가리킨다. 한 블록씩 따라가는 방식보다 여러 가용 주소를 쉽게 확보한다.')),
sec('14.5.4','계수',573,573,
 p('연속 블록들이 함께 할당·반환되는 경향을 이용하여 첫 주소와 연속 길이만 기록한다. 개별 항목은 주소 하나보다 크지만 대개 길이가 1보다 커 전체 목록이 짧아진다. 효율적인 검색·삽입·삭제를 위해 균형 트리로 저장할 수 있다. 익스텐트 관리와 유사한 구조이다.')),
sec('14.5.5','공간맵',573,574,
 p('큰 파일 시스템에서 산재한 블록을 반환할 때 비트맵 여러 블록을 갱신하는 비용이 커질 수 있다. ZFS는 장치를 **메타슬랩**으로 나누고 각 영역의 **공간맵**에 할당·반환 활동을 계수 형식으로 시간순 기록한다.'),
 steps('공간맵 사용','필요한 메타슬랩의 공간맵을 오프셋으로 색인된 메모리의 균형 트리로 적재한다.','로그를 재실행하여 현재의 할당·가용 상태를 반영한다.','인접 가용 구간을 결합하여 항목을 압축한다.','트랜잭션 작업의 일부로 장치의 공간 정보를 갱신한다. 처리 중 새 요청은 로그를 통해 충족시킬 수 있다.'),
 p('로그와 균형 트리가 함께 가용 리스트 역할을 수행하여 구조 크기와 I/O를 제어한다.')),
sec('14.5.6','사용하지 않는 트림',574,574,
 p('HDD는 해제된 블록을 다음 사용 때 덮어쓰면 되지만 NAND는 먼저 큰 블록을 지워야 한다. 파일 시스템이 어느 페이지가 더 이상 사용되지 않는지 장치에 알려야 미리 가비지 수집·삭제하여 쓰기 가능한 공간을 유지할 수 있다. 원문은 ATA의 **TRIM**, NVMe의 **unallocate** 명령을 제시한다. 이 기능이 없으면 거의 가득 찼을 때 쓰기 중 정리가 집중되어 성능이 급락하는 **쓰기 절벽(write cliff)**이 생길 수 있다.')),
sec('14.6.1','효율',574,576,
 p('공간 효율과 성능은 함께 판단한다. inode 선할당은 공간을 쓰지만 데이터 근처에 분산하면 탐색을 줄인다. 큰 클러스터는 전송에 유리하지만 내부 단편화가 커, 작은 파일·마지막 부분에 작은 클러스터를 쓰는 변형이 있다. 마지막 접근 시각을 유지하려면 읽기 때도 메타데이터 기록이 필요하여 각 속성의 실제 가치와 비용을 고려해야 한다.'),
 p('큰 포인터는 표현 가능한 파일·공간을 늘리지만 색인·가용 공간 구조의 크기도 키운다. 고정 크기 테이블은 가득 차면 자원이 남아도 새 프로세스·파일을 만들지 못하고 크기 변경에 재부팅·재컴파일이 필요할 수 있다. 동적 할당은 이런 인위적 제한을 줄이지만 관리 알고리즘이 복잡해지고 할당·반환 비용이 생긴다. 원문의 과거 MS-DOS·Solaris 사례는 초기 구조 선택이 향후 확장에 미치는 영향을 보여준다.')),
sec('14.6.2','성능',576,579,
 p('컨트롤러 캐시는 트랙·블록을 보관하고 운영체제는 메모리에 다시 캐시한다. **페이지 캐시**는 가상 메모리의 페이지로 파일 데이터를 관리하고 프로세스 페이지와 함께 이용할 수 있다. 메모리 사상 접근은 페이지 캐시, read/write는 별도 버퍼 캐시를 쓰면 동일 데이터가 두 번 복사되는 **이중 캐싱**이 생겨 공간·CPU·일관성 비용이 든다. **통합 버퍼 캐시**는 두 접근 경로가 같은 캐시를 사용하게 한다.'),
 fig(c,578,'O14-F03','그림 14.11 통합 버퍼 캐시를 사용하는 입출력',(0.33,0.102,0.75,0.333),'메모리 맵드 I/O와 read/write의 두 경로가 하나의 캐시를 거쳐 파일 시스템으로 이어진다.'),
 p('프로세스 메모리와 파일 캐시가 가용 메모리를 공유하면 한쪽이 다른 쪽을 밀어낼 수 있어 교체 정책과 경계를 조정한다. 원문의 Solaris 발전은 단순한 범용 정책만으로 모든 부하를 만족시키기 어렵다는 사례이다.'),
 tab(['기법','원문의 조건·효과'],[['동기식 쓰기','저장장치에 도달한 뒤 진행한다. 메타데이터·순서 보장이 필요한 작업에 사용한다.'],['비동기식 쓰기','캐시에 쓰고 먼저 복귀한다. 모아서 스케줄할 수 있지만 실제 매체 기록은 뒤에 이루어진다.'],['free-behind','순차 접근에서 다음 페이지를 요청하면 이전 페이지를 버퍼에서 제거한다.'],['read-ahead','요청 페이지와 이어질 페이지를 한 번에 읽어 미리 캐시한다. 순차 접근에서 이후 요청 가능성을 이용한다.']]),
 p('순차 파일은 최근 페이지를 다시 쓸 가능성이 낮아 일반 LRU가 적합하지 않을 수 있다. 작은 비동기 출력은 캐싱 덕분에 입력보다 빠르게 보일 수 있지만 파일이 캐시 용량보다 크면 결국 장치 속도에 제약된다. 따라서 캐시가 대량 연속 I/O의 물리 병목을 없애는 것은 아니다.')),
sec('14.7.1','일관성 검사',579,580,
 p('파일 생성 같은 작업은 디렉터리·FCB·데이터·가용 계수 등 여러 구조를 바꾼다. 일부만 기록되고 크래시가 나면 메모리와 장치 또는 자료구조 사이가 불일치한다. **일관성 검사기**는 디렉터리와 메타데이터를 실제 할당 상태와 비교하여 복구한다. 전체 검사는 오래 걸리므로 갱신 중 상태 비트를 설정하고 완료 후 소거하여 필요할 때 검사할 수 있다.'),
 p('복구 가능성은 할당 구조에 좌우된다. 원문은 데이터 블록의 링크가 있으면 재구성이 가능하지만 서로 관계를 모르는 색인 데이터 블록은 디렉터리 정보를 잃었을 때 어렵다고 설명한다. 메타데이터의 동기식 기록과 전원 보호 장치 버퍼는 일부 위험을 줄여도 크래시 도중 부분 갱신을 모두 없애지는 못한다.')),
sec('14.7.2','로그 구조 파일 시스템',580,581,
 steps('원문의 로그 기반 복구','파일 시스템 메타데이터 변경을 로그에 순차 기록하고 한 작업의 연산 집합을 트랜잭션으로 묶는다.','로그 기록이 확약되면 호출자에게 복귀할 수 있다. 이후 실제 자료구조에 변경을 재실행하고 진행·완료를 기록한다.','크래시 뒤에는 확약되었지만 미완료인 트랜잭션을 끝까지 적용한다.','확약 전에 중단된 트랜잭션의 변경은 원상 복구하여 일관성을 회복한다.'),
 p('로그는 원형 버퍼로 구현될 수 있으므로 아직 필요한 정보를 새 기록으로 덮지 않게 관리한다. 전체 메타데이터를 검사·수리하는 대신 필요한 로그를 처리하므로 복구의 지연·불확실성·사람의 개입을 줄인다. HDD에서는 동기식 임의 메타데이터 쓰기를 순차 로그 쓰기로 바꾸고 실제 구조 갱신을 비동기로 수행하여 성능도 높일 수 있다.')),
sec('14.7.3','다른 해결 방안들',581,582,
 p('WAFL과 ZFS의 다른 접근은 기존 블록을 새 내용으로 덮지 않고 데이터·메타데이터 변경을 새 블록에 기록하는 것이다. 트랜잭션이 끝나면 포인터를 새 블록으로 바꾸고 옛 블록을 회수한다. 옛 포인터·블록을 유지하면 특정 시점의 **스냅숏**이 된다. 포인터 갱신의 정확성이 중요하며 WAFL도 일부 메타데이터 오염에 대응하는 검사기를 가진다고 원문은 설명한다. ZFS는 여기에 데이터·메타데이터 체크섬과 RAID를 결합하는 방식으로 소개된다.')),
sec('14.7.4','백업과 복구',582,583,
 steps('원문의 주기적 백업','첫날 전체 파일을 전체 백업한다.','다음 날부터 직전 백업 이후 바뀐 파일만 점증적으로 백업한다.','일정 주기가 지나면 다시 전체 백업으로 돌아간다.','복원은 전체 백업에서 시작하여 이후 필요한 점증 백업을 차례로 적용한다.'),
 p('주기가 길면 백업량을 줄일 수 있지만 복원에 읽을 매체가 많아진다. 중간 전체 백업은 복원 부담을 줄이는 대신 저장 공간을 더 쓴다. 손상 발견이 늦을 수 있어 재사용하지 않는 영구 백업과 다른 장소의 보관도 필요할 수 있다. 백업은 시스템 전체 고장뿐 아니라 실수로 삭제한 파일의 복구에도 이용된다.')),
sec('14.8','예: WAFL 파일 시스템',583,587,
 p('**WAFL(write-anywhere file layout)**은 원문의 NetApp 파일 서버와 NVRAM 쓰기 캐시·랜덤 I/O 부하에 맞춰 설계되었다. 블록 기반이며 inode를 사용하고, 루트 inode 아래에 inode 파일·가용 블록 맵·가용 inode 맵 등을 모두 파일로 둔다. 메타데이터도 일반 파일이므로 고정 위치에 묶이지 않고 여러 디스크로 확장할 때 함께 커질 수 있다.'),
 steps('WAFL 스냅숏','루트 inode를 복사하여 특정 시점의 포인터를 남긴다.','이후 변경은 기존 블록을 덮지 않고 새 공간에 기록한다. 현재 루트는 새 블록을 가리키고 스냅숏은 옛 블록을 계속 가리킨다.','추가 맵 비트는 어느 스냅숏이 블록을 쓰는지 추적한다. 그 블록을 쓰는 모든 스냅숏이 없어지면 재사용할 수 있다.'),
 fig(c,585,'O14-F04','그림 14.13 WAFL의 스냅숏',(0.35,0.501,0.675,0.936),'스냅숏 전, 포인터만 복사한 직후, 블록 D를 D′로 변경한 뒤의 세 상태이다. 옛 블록을 남기고 새 블록에 기록하는 관계를 보존한다.'),
 p('스냅숏은 전체 파일을 복사하지 않아 적은 공간으로 여러 시점을 보관하고 백업·테스트·디버깅에 쓸 수 있다. **클론**은 읽기·쓰기 스냅숏으로 원본 스냅숏을 참조하다 변경을 새 블록에 기록한다. 원본을 유지하므로 테스트·업그레이드 실패 때 클론만 제거할 수 있고, 필요하면 원본을 대신하도록 승격할 수 있다. 원격 복제는 처음 스냅숏을 전송한 뒤 이후 스냅숏 사이에 바뀐 블록과 포인터를 적용하여 다른 시스템의 복사본을 유지한다.'),
 p('원문의 별도 APFS 설명은 공간 공유, 복제·스냅숏, 쓰기 시 복사, 암호화, 디렉터리 크기 관리, 원자적 안전 저장, I/O 병합을 소개한다. 컨테이너의 가용 공간을 여러 파일 시스템이 공유하고, 작은 쓰기를 큰 쓰기로 묶어 NVM 성능을 돕는 관계를 설명한다. 이 기능 목록의 상세 동작을 외부 지식으로 보충하지 않는다.')),
sec('14.9','요약과 원문 연습문제의 점검 범위',587,590,
 p('원문 요약은 계층·할당·가용 공간·디렉터리와 안정성의 관계를 다시 정리한다. 연습문제는 블록 추가·제거에 따른 할당 방식별 I/O, 비트맵의 저장, 할당 선택 기준, 확장 영역, 캐시의 한계, 동적 테이블의 이익·비용을 다룬다. 원문에 없는 횟수 계산이나 풀이를 생성하지 않았다. 추가 자료와 참고문헌의 존재를 확인하고 외부 설명은 사용하지 않았다.'))]
c['comparisons']=[{'title':'세 가지 파일 할당','source':src(562,570),'headers':['방법','이점','중요 제약'],'rows':[['연속','빠른 순차·직접 접근','외부 단편화·성장·선할당'],['연결','동적 확장·외부 단편화 회피','직접 접근·포인터 비용과 손상'],['색인','외부 단편화 없이 직접 접근','색인 공간·색인 접근 I/O']]},{'title':'원문의 복구 방식','source':src(579,583),'headers':['방법','기준'],'rows':[['일관성 검사','현재 구조를 검사해 불일치를 복구한다.'],['로그 기반','확약 로그의 재실행·미확약 변경의 복구를 수행한다.'],['새 블록 기록·스냅숏','옛 내용은 남기고 포인터를 새 내용으로 전환한다.'],['백업 복원','다른 매체의 전체·점증 사본에서 내용을 되살린다.']]}]
c['key_points']=['파일 인터페이스와 실제 블록 배치는 계층별로 연결되며 FCB·디렉터리·열린 테이블의 역할이 다르다.','연속·연결·색인의 차이는 접근 속도뿐 아니라 확장·단편화·포인터·복구에 걸쳐 있다.','원문의 비트맵은 1=가용, 0=할당이다.','TRIM은 파일 시스템의 해제 사실을 NAND 장치에 알려 미리 공간을 준비하게 한다.','캐시·비동기 쓰기는 빠른 반환과 실제 기록 완료를 구별해야 하며 로그·스냅숏·백업의 목적도 다르다.']
c['review']=['inode의 직접·간접 수준과 FAT의 사슬은 파일 내용의 위치를 찾는 서로 다른 구조이다.','가용 공간은 비트맵·연결·그룹·계수·로그/트리의 여러 방식으로 관리한다.','HDD의 헤드 이동 최적화를 NVM에 그대로 적용하면 불필요한 CPU 비용이 될 수 있다.','WAFL은 새 블록 기록과 루트 포인터의 보존으로 스냅숏·클론·복제를 연결한다.']
c['index_terms']=[{'term':t,'section':s} for t,s in [('FCB','14.1'),('익스텐트','14.4.1'),('FAT','14.4.2'),('색인 할당','14.4.3'),('inode','14.4.3'),('공간맵','14.5.5'),('TRIM','14.5.6'),('통합 버퍼 캐시','14.6.2'),('로그 기반 복구','14.7.2'),('WAFL','14.8'),('스냅숏','14.8')]]
c['verification']['visually_checked_pdf_pages'] += [568,571]
c['verification']['notes']=['PDF554~590 전 페이지를 읽고 본문·도표·연습문제·참고문헌 범위를 검토했다.','FAT 사슬217→618→339, inode 직접/간접 도표, 통합캐시, WAFL D→D′ 스냅숏을 이미지로 대조·보존했다.','인쇄631쪽의포인터1024개·2단계4GB와634쪽의가용비트표기·첫블록수식을이미지로대조했다. 원문표기와순서를유지했다.']
finish(c)

c=chapter(13,'파일 시스템 인터페이스',517,553,
 ['파일이라는 논리적 저장 단위와 속성·연산·접근 방법을 정리한다. 디렉터리의 이름 구조가 공유·탐색·삭제에 미치는 영향을 비교하고 파일 보호와 메모리 사상 파일의 동작을 살펴본다.'],
 ['파일·속성·연산 → 유형·구조와 내부 단편화 → 순차/직접/색인 접근 → 디렉터리 구조 → 접근 보호 → 메모리 사상과 공유'])
c['sections']=[
sec('13.1','파일 개념',517,518,
 p('**파일**은 보조저장장치에 기록된 관련 정보의 집합이며, 운영체제는 저장장치의 물리 특성을 추상화하여 일관된 논리적 저장 단위로 제공한다. 일반적으로 비휘발성 장치에 사상되므로 재부팅 뒤에도 내용이 존속한다. 사용자에게는 논리적 보조저장장치의 최소 할당 단위이다. 내용의 의미는 작성자·사용자가 정하며 비트·바이트·행·레코드의 연속이나 프로그램·데이터 등으로 해석한다.'),
 p('파일 시스템은 실제 파일의 집합과 모든 파일의 정보를 제공하는 디렉터리 구조로 이루어진다. 파일 인터페이스는 원래의 저장 용도를 넘어 proc 파일 시스템의 시스템 정보 접근에도 이용된다.')),
sec('13.1.1','파일 속성',518,519,
 tab(['속성','원문의 역할'],[['이름','사람이 읽는 기호형 이름'],['식별자','파일 시스템 안에서 파일을 고유하게 구별하는 숫자 등의 꼬리표'],['유형','여러 파일 유형을 지원할 때 필요한 정보'],['위치','장치와 그 장치 안의 위치를 나타내는 포인터'],['크기','현재 크기와 최대 허용 크기'],['보호','읽기·쓰기·실행 등의 접근 통제'],['타임스탬프·사용자 식별','생성·변경·사용 시각과 보호·보안·감시 정보']]),
 p('이름의 대소문자 구별은 시스템마다 다르다. 파일은 만든 프로세스와 독립적으로 존속하고 복사·전송될 수 있지만 공유·동기화 수단이 없다면 사본은 서로 독립적으로 바뀐다. 확장 속성에는 문자 인코딩·체크섬 같은 정보가 포함될 수 있다. 디렉터리 항목은 보통 이름과 식별자를 두고 식별자로 다른 속성을 찾는다. 디렉터리도 비휘발성으로 유지해야 하므로 저장장치에 보관하고 필요한 부분만 메모리에 반입한다.')),
sec('13.1.2','파일 연산과 열린 파일 관리',520,524,
 tab(['연산','핵심 작업'],[['생성','공간을 확보하고 디렉터리 항목을 만든다.'],['열기','이름·요청 모드·권한을 확인하고 후속 호출에 쓸 핸들을 반환한다.'],['쓰기·읽기','핸들로 데이터를 전달하며 현재 파일 위치를 갱신한다.'],['위치 재설정(seek)','현재 위치를 설정한다. 실제 I/O가 반드시 필요한 것은 아니다.'],['삭제','항목과 공간을 해제한다. 하드 링크가 있으면 마지막 링크가 없어질 때까지 내용은 남는다.'],['절단','다른 속성을 유지하며 길이를 0으로 하고 공간을 해제할 수 있다.']]),
 p('매번 이름을 검색하지 않도록 **열린 파일 테이블**을 사용한다. 대부분의 시스템은 명시적 open을 요구하며 접근 모드를 권한과 비교한다. 닫으면 관련 테이블 항목과 락을 해제할 수 있다. 여러 프로세스가 동시에 여는 시스템은 **프로세스별 테이블**에 현재 위치·접근 권한 등을, **범 시스템 테이블**에 장치 위치·크기·접근 날짜 등 프로세스 독립 정보를 둔다. 프로세스별 항목이 범 시스템 항목을 가리킨다. 열린 계수는 마지막 사용자가 닫아 0이 될 때 항목을 회수하도록 한다.'),
 p('현재 위치 포인터는 각 프로세스의 사용 상태이므로 디스크상의 고유 속성과 분리한다. 열린 계수는 하드 링크 참조 계수와 구별하여 문맥에 맞게 읽는다. 전자는 열린 테이블의 수명에, 후자는 같은 파일에 대한 이름 참조와 파일 내용의 삭제에 관련된다.'),
 tab(['락의 구분','동작'],[['공유 / 배타','공유 락은 여러 프로세스가 함께 획득할 수 있고, 배타 락은 한 프로세스만 가진다. 모든 운영체제가 둘 다 지원하지는 않는다.'],['강제적(mandatory)','운영체제가 잠긴 파일에 다른 프로세스가 접근하지 못하게 한다.'],['권고적(advisory)','응용이 협조하여 락을 획득·해제해야 하며 운영체제가 모든 접근을 차단하지는 않는다.']]),
 p('락은 접근할 때만 유지하도록 하며 여러 락의 획득으로 교착 상태가 생기지 않게 해야 한다. 원문의 Java 예는 FileChannel을 얻고 처음 부분의 배타 락과 나머지 부분의 공유 락을 획득한 뒤 release로 해제한다. 아래 코드는 원문을 이미지로 보존한다. 원문에 실행 결과 미제시.'),
 fig(c,524,'O13-F01','그림 13.2 Java의 파일 락킹 예제',(0.175,0.10,0.91,0.835),'원문의 EXCLUSIVE=false, SHARED=true, lock 인자와 finally의 해제 처리를 보존한다. 데이터 수정·읽기의 본문은 원래부터 주석으로만 제시된다.')),
sec('13.1.3','파일 유형',525,526,
 p('운영체제가 파일 유형을 인식하면 유형에 맞는 연산을 선택하거나 부적절한 연산을 막을 수 있다. 이름의 확장자, 작성 프로그램 속성, 시작 부분의 매직 넘버가 원문의 식별 방법이다. 확장자는 실행 가능·소스·목적·배치·문서·라이브러리·보관·멀티미디어 등의 용도를 암시한다. 그러나 모든 시스템에서 확장자가 강제되는 것은 아니며 응용의 힌트일 수도 있다.'),
 p('원문의 macOS 예는 작성 프로그램을 파일 속성으로 기록하여 데이터 파일을 열 때 해당 프로그램을 실행한다. UNIX는 일부 파일의 시작 부분 매직 넘버를 쓰지만 모든 파일이 이를 가지지는 않는다. 확장자와 작성 프로그램의 취급도 시스템마다 다르므로 특정 식별법을 보편 규칙으로 확대하지 않는다.')),
sec('13.1.4','파일 구조',526,527,
 p('파일 유형은 내부 구조를 암시한다. 운영체제가 여러 구조를 직접 지원하면 편리한 연산을 제공할 수 있지만 코드가 커지고 복잡해지며 새로운 구조의 응용을 제약할 수 있다. 원문의 텍스트·실행 파일만 지원하는 가정에서는 암호화 데이터가 어느 유형에도 맞지 않는 문제가 생긴다. 반대로 UNIX처럼 바이트열로 다루면 유연하지만 해석과 운용은 응용의 책임이 된다. 다만 프로그램 적재·실행을 위해 실행 파일의 구조는 운영체제가 이해해야 한다.')),
sec('13.1.5','파일의 내부 구조',527,527,
 p('논리 레코드 크기와 물리 블록 크기는 다를 수 있어 여러 레코드를 한 블록에 **패킹**하거나 다시 풀어야 한다. UNIX의 바이트 스트림은 파일 시작부터의 오프셋으로 바이트를 지정하고 파일 시스템이 물리 블록으로 묶는다. 이 변환은 응용이나 운영체제가 담당할 수 있다.'),
 p('공간은 블록 단위로 할당하므로 마지막 블록 일부가 남는 **내부 단편화**가 발생한다. 원문 예는 512바이트 블록에서 1,949바이트 파일에 네 블록(2,048바이트)을 할당하여 99바이트가 남는 경우이다. 블록을 크게 하면 이 낭비가 커질 수 있다.')),
sec('13.2.1','순차 접근',528,528,
 p('**순차 접근**은 저장된 레코드 순서로 파일을 처리한다. read-next는 다음 부분을 읽고 현재 위치를 증가시키며, 쓰기는 끝에 추가하고 새 끝으로 포인터를 옮긴다. 되감기나 정해진 레코드 수만큼의 이동을 제공할 수도 있다. 테이프 모델에 기반하지만 순차 장치와 임의 접근 장치 모두에 사용할 수 있고 편집기·컴파일러가 예로 제시된다.')),
sec('13.2.2','직접 접근',528,529,
 p('**직접(상대) 접근**은 고정 길이 레코드·블록을 번호로 지정하여 읽기·쓰기를 임의 순서로 수행한다. read(n)·write(n) 또는 position-file(n) 후 순차 연산으로 표현할 수 있다. 사용자가 보는 상대 블록 번호는 실제 디스크 주소와 다르며 운영체제가 위치를 할당하고 다른 파일 영역의 접근을 막는다. 번호의 시작이 0인지 1인지는 시스템에 따라 다르다.'),
 formula('L × N 위치에서 L바이트','0번을 첫 레코드로 세고 논리 레코드의 길이가 L일 때 N번째 레코드의 요청 위치이다. 고정 길이라는 전제를 유지한다.',['L: 논리 레코드 길이','N: 0부터 세는 레코드 번호']),
 p('직접 접근으로 순차 접근을 구현하는 것은 간단하지만 순차 접근만으로 직접 접근을 흉내 내는 것은 비효율적이다. 원문의 항공편 번호로 예약 블록을 찾는 사례는 원하는 블록을 먼저 결정한 뒤 직접 읽는 의미를 보여준다.')),
sec('13.2.3','기타 접근 방법',529,531,
 p('**색인 접근**은 먼저 레코드의 색인에서 포인터를 찾은 뒤 해당 블록을 직접 읽는다. 파일이 커 색인도 메모리에 못 들어가면 색인 파일에 대한 상위 색인을 둘 수 있다. 원문의 ISAM은 작은 마스터 색인→2차 색인 블록→실제 파일 블록의 순서로 찾고 블록 안에서 검색한다.'),
 p('원문의 UPC 가격 예는 10자리 코드와 6자리 가격의 16바이트 레코드, 1,024바이트 블록당 64레코드, 블록의 첫 UPC로 구성한 메모리 색인을 설명한다. 다만 120,000레코드를 2,000블록·색인 2,000항목으로 설명하는 수치 연결은 **원문 확인 필요**이다. 원문 수치를 다른 값으로 고쳐 계산하지 않고, 색인에서 블록을 정하여 적은 I/O로 탐색한다는 구조를 보존한다.')),
sec('13.3','디렉터리 구조',531,531,
 p('**디렉터리**는 파일 이름을 파일 제어 블록에 대응시키는 심볼 테이블로 볼 수 있다. 필요한 연산은 이름·패턴 검색, 생성·삭제, 항목 나열, 이름 변경, 전체 순회이다. 이름이 커져 항목에 맞지 않거나 삭제로 빈 공간이 생기면 공간 관리도 필요하다. 순회는 검색뿐 아니라 백업·보관과 공간 회수에도 이용된다.')),
sec('13.3.1','1단계 디렉터리',532,532,
 p('모든 파일을 한 디렉터리에 두므로 개념이 단순하지만 모든 이름이 고유해야 한다. 사용자나 파일 수가 늘면 이름 충돌과 기억·관리 문제가 커진다. 긴 이름을 허용해도 파일을 조직하는 문제 자체가 없어지지는 않는다.')),
sec('13.3.2','2단계 디렉터리',532,534,
 p('마스터 파일 디렉터리(**MFD**)가 사용자별 파일 디렉터리(**UFD**)를 가리킨다. 각 UFD 안에서만 이름이 고유하면 되므로 다른 사용자는 같은 파일명을 쓸 수 있다. 생성·삭제는 자신의 UFD만 검색하고 UFD의 생성·삭제는 적절한 관리 권한이 필요하다. 사용자 간 격리는 되지만 다른 사용자의 파일을 공유하려면 접근 허용과 사용자명+파일명의 경로가 필요하다.'),
 p('시스템 프로그램을 모든 UFD에 복사하면 공간을 낭비한다. 대신 현재 UFD에서 찾지 못하면 시스템 파일 디렉터리 등 정해진 순서를 찾는 **탐색 경로**를 둔다. 사용자가 자신의 경로를 가질 수도 있다. 볼륨 문자·디렉터리·버전의 경로 구문은 시스템마다 다르다.')),
sec('13.3.3','트리 구조 디렉터리',534,536,
 p('2단계를 임의 높이로 확장하면 사용자가 하위 디렉터리를 만드는 트리가 된다. 최상위 루트와 파일별 고유 경로를 갖는다. 디렉터리도 특별 취급되는 파일로 구현할 수 있으며 일반 파일과 구별하고 별도 생성·삭제 연산을 사용한다. 프로세스의 **현재 디렉터리**를 기준으로 파일을 찾고, 자식 프로세스는 보통 부모의 현재 디렉터리를 따른다.'),
 tab(['경로','기준'],[['절대 경로','루트부터 목적 파일까지 명시'],['상대 경로','현재 디렉터리부터 목적 파일까지 명시']]),
 p('원문 예에서 현재 디렉터리가 /spell/mail이면 prt/first와 /spell/mail/prt/first는 같은 파일을 가리킨다. 디렉터리 삭제는 비어 있을 때만 허용하는 정책과 하위 내용을 함께 재귀 삭제하는 정책이 있다. 후자는 편하지만 한 명령의 실수로 많은 내용을 잃을 수 있다. 트리에서는 경로와 접근 허용을 통해 다른 사용자 파일에도 접근할 수 있다.')),
sec('13.3.4','비순환 그래프 디렉터리',537,539,
 p('**비순환 그래프**는 파일·하위 디렉터리를 여러 곳에서 공유하도록 트리를 일반화한다. 물리적으로 같은 파일을 공유하면 수정이 다른 참조에도 반영되지만 독립 사본 둘은 그렇지 않다. 링크는 다른 파일의 경로를 가진 간접 포인터로 구현할 수 있다. 동일 항목 내용을 여러 디렉터리에 복사하는 방식은 속성 변경을 일치시켜야 하는 문제가 있다.'),
 fig(c,537,'O13-F02','그림 13.10 비순환 그래프 디렉터리 구조',(0.28,0.60,0.77,0.94),'여러 경로가 동일한 파일·서브디렉터리로 이어지는 공유 관계를 보여준다.'),
 p('여러 절대 경로가 한 파일을 가리키므로 탐색·통계·백업에서 같은 대상을 중복 처리하지 않아야 한다. 공유 파일을 한 참조만 지웠다고 제거하면 **dangling pointer**가 생긴다. 심볼릭 링크는 원래 파일이 삭제되면 없는 이름을 가리킬 수 있으며, 접근 시 해석 실패로 처리하거나 따로 관리할 수 있다. 같은 이름의 새 파일이 생기는 문제도 고려해야 한다.'),
 p('다른 방식은 모든 참조가 없어질 때까지 파일을 유지하는 것이다. 가변 길이 참조 목록 대신 **참조 계수**를 두어 링크 추가 때 증가, 삭제 때 감소시키고 0일 때 파일을 지울 수 있다. 원문 UNIX의 하드 링크는 inode에 이 계수를 유지한다. 디렉터리에 대한 다중 참조를 제한하는 것은 비순환성을 지키는 데 도움이 된다.')),
sec('13.3.5','일반 그래프 디렉터리',539,541,
 p('기존 구조에 링크를 추가하면 순환이 생길 수 있다. **일반 그래프**는 공유의 유연성이 크지만 잘못된 탐색은 무한 반복할 수 있고 순환 내부의 참조 계수가 0이 되지 않아 도달 불가능한 공간을 회수하지 못할 수 있다.'),
 steps('원문의 가비지 수집','파일 시스템을 순회하면서 접근 가능한 모든 대상을 표시한다.','두 번째 탐색에서 표시되지 않은 대상을 수집하여 가용 공간 목록에 넣는다.'),
 p('디스크 기반 전체 탐색은 비용이 커 드물게 쓰인다. 링크 추가 시 순환 검사도 비싸다. 디렉터리 순회에서 링크를 따라가지 않거나 탐색 수를 제한하는 등의 방안을 고려한다. 비순환 구조는 검색과 마지막 참조 판단이 상대적으로 간단하다는 점과 대조된다.')),
sec('13.4.1','보호와 접근의 유형',541,542,
 p('**신뢰성**은 물리 손상·사고·오류에서 내용을 보존하는 문제이고 **보호**는 부적절한 접근을 통제하는 문제이다. 복사본·백업은 신뢰성에, 인증·암호화·방화벽과 파일별 접근 권한은 보호에 관계된다. 모든 접근 금지나 완전 개방 대신 필요한 연산을 통제한다.'),
 bullets('통제할 수 있는 기본 연산: 읽기, 쓰기, 실행, 끝에 추가, 삭제, 이름·속성 나열, 속성 변경.','이름 변경·편집·복사 같은 고급 작업은 기본 연산의 조합이므로 기본 연산에서 보호를 적용할 수 있다.','규모와 목적에 따라 보호 요구가 다르므로 모든 환경에 같은 정책을 무조건 적용하지 않는다.')),
sec('13.4.2','접근 제어',542,545,
 p('**ACL(접근 제어 리스트)**은 파일·디렉터리에 누가 어떤 연산을 할 수 있는지 연결한다. 요청 사용자의 신원과 연산을 목록에서 검사한다. 세밀하지만 사용자를 일일이 열거하면 목록이 길어지고 디렉터리 공간 관리가 복잡해진다. 이를 줄이기 위해 소유자·그룹·기타 사용자로 분류하고 필요한 대상에 ACL을 더하는 결합 방식을 쓸 수 있다.'),
 tab(['UNIX 권한','원문의 의미'],[['r','파일 읽기. 디렉터리에서는 내용 열람을 제어한다.'],['w','쓰기 접근을 제어한다.'],['x','파일 실행. 디렉터리에서는 해당 디렉터리로 이동하는 데 필요하다.'],['세 사용자 필드','소유자·그룹·기타에 각 rwx 3비트, 총 9비트']]),
 p('원문의 Sara 사례는 책 전체를 공동 작업하는 그룹과 한 장만 접근시킬 방문자의 요구를 구분한다. 그룹 하나만으로 부족할 때 해당 장의 ACL에 방문자를 추가한다. 권한·ACL을 바꾸는 행위 자체도 엄격히 통제해야 한다. 두 허가가 충돌할 때의 우선순위도 정책으로 정해야 하며, 원문의 Solaris 사례는 더 구체적으로 부여된 ACL을 우선한다. 명시한 시스템의 규칙을 모든 시스템에 확대하지 않는다.')),
sec('13.4.3','다른 보호 방법',545,546,
 p('파일마다 암호를 요구할 수도 있지만 암호가 너무 많으면 기억하기 어렵고 하나를 공통 사용하면 유출 시 전부 노출된다. 디렉터리별 암호나 파일·파티션 암호화가 대안으로 제시되며 암호 관리가 중요하다.'),
 p('디렉터리는 파일과 다른 연산을 가지므로 생성·삭제·목록 조회 등을 별도로 보호해야 한다. 이름이나 존재 자체가 중요한 정보일 수 있다. 경로로 파일에 접근하려면 파일뿐 아니라 그 경로의 디렉터리 접근도 허용되어야 한다. 여러 경로가 있으면 어떤 경로를 쓰는가에 따라 접근 권한이 다를 수 있다.')),
sec('13.5.1','메모리 사상 파일의 기본 기법',546,548,
 p('**메모리 사상 파일**은 프로세스 가상 주소의 일부를 파일 블록과 대응시킨다. 처음 참조할 때 요구 페이징으로 페이지 폴트가 발생하여 해당 내용을 메모리로 읽고, 이후에는 메모리 접근으로 처리한다. 매 접근마다 read/write 시스템 콜을 하는 부담을 줄인다. 사상했다고 파일 전체가 즉시 적재되는 것은 아니다.'),
 p('메모리에 쓴 내용이 보조저장장치에 즉시 동기 기록되는 것은 아니다. 기록·닫기·메모리 확보 시 처리는 원문이 설명한 시스템의 정책에 따른다. 어떤 시스템은 명시적 사상 호출을 요구하며 Solaris는 일반 파일 I/O도 커널 주소 공간의 매핑을 통해 처리하는 사례로 소개된다.'),
 p('여러 프로세스의 페이지 테이블이 같은 물리 페이지를 가리키면 같은 파일의 변경을 공유할 수 있다. **쓰기 시 복사**를 사용하면 읽기 전용으로 공유하다 수정할 때 별도 페이지를 만든다. 공유 내용의 동시 수정이 필요하면 상호 배제 기법도 사용해야 한다. 같은 파일을 여러 주소 공간에 사상하는 방법은 공유 메모리 통신을 구현하는 데 쓰인다.')),
sec('13.5.2','Windows API에서 공유 메모리',548,551,
 steps('원문의 생산자·소비자 흐름','생산자가 CreateFile()로 temp.txt를 열고 HANDLE을 얻는다.','CreateFileMapping()으로 SharedObject라는 이름의 공유 메모리 객체를 만든다.','MapViewOfFile()로 자신의 가상 주소 공간에 뷰를 만들고 반환 포인터로 메시지를 기록한다.','소비자는 OpenFileMapping()으로 같은 이름의 객체를 열고 MapViewOfFile()로 뷰를 만든다.','소비자가 메시지를 읽고, 각 프로세스는 UnmapViewOfFile()과 CloseHandle()로 뷰·핸들을 정리한다.'),
 p('뷰는 전체 파일 또는 오프셋·크기로 지정한 일부일 수 있다. 원문은 마지막 세 인자를 0으로 두어 전체 파일의 뷰를 지정한다. 실제 페이지는 요구 페이징으로 접근할 때 적재된다. 아래 생산자·소비자 코드는 원문 그대로 이미지로 보존한다. 본문에 메시지 읽기가 설명되어 있지만 별도 실행 출력 화면은 원문에 실행 결과 미제시.'),
 fig(c,549,'O13-F03','그림 13.15 공유 메모리에 기록하는 Windows 생산자',(0.16,0.108,0.92,0.789),'temp.txt와 SharedObject, 원문 API 인자·주석·정리 순서를 그대로 보존한 전체 코드이다.'),
 fig(c,550,'O13-F04','그림 13.16 공유 메모리를 읽는 Windows 소비자',(0.165,0.46,0.91,0.943),'동일한 SharedObject의 뷰를 만들고 포인터로 읽는 원문 전체 코드이다. 출력 문자열을 새로 실행하거나 결과를 추정하지 않는다.')),
sec('13.6','요약과 원문 연습문제의 점검 범위',551,553,
 p('파일은 논리 레코드를 물리 저장장치에 대응시키는 추상 자료형이며 디렉터리는 이름과 조직을 제공한다. 구조가 1단계→2단계→트리→공유 그래프로 확장될수록 유연성과 함께 탐색·삭제·공간 회수의 복잡성이 증가한다. 파일 보호는 사용자뿐 아니라 연산의 종류와 경로·디렉터리를 함께 고려한다.'),
 p('장말 문제는 파일 보관 정책, 유형·구조 지원, 이름과 디렉터리 조직, open/close, 디렉터리 보호, 권한 표현과 제어 리스트를 점검한다. 본문에 없는 문제 풀이를 추가하지 않는다. 추가 자료의 다중 레벨 디렉터리·NFS 소개와 참고문헌 존재를 확인했고 외부 내용을 보충하지 않았다.'))]
c['comparisons']=[{'title':'디렉터리 구조의 변화','source':src(532,541),'headers':['구조','해결·허용하는 것','새 제약'],'rows':[['1단계','단순한 한 디렉터리','모든 파일명 고유'],['2단계','사용자별 같은 이름','공유와 경로 표현 필요'],['트리','사용자 하위 디렉터리·계층화','물리적 파일·하위 디렉터리 공유 제한'],['비순환 그래프','공유 허용','중복 순회·참조·삭제 관리'],['일반 그래프','순환까지 허용하는 유연성','탐색 종료·도달성·가비지 수집 문제']]}]
c['key_points']=['파일의 이름·식별자·장치 위치, 파일 포인터·열린 계수·링크 참조 계수를 문맥별로 구별한다.','공유 파일은 독립 사본과 다르며 링크와 참조 계수는 삭제 시점을 바꾼다.','순차 접근, 상대 블록 번호에 의한 직접 접근, 색인에 의한 블록 선택을 구분한다.','일반 그래프에서 순환은 탐색과 참조 계수 기반 회수에 문제를 만든다.','ACL·사용자 분류·디렉터리 권한과 메모리 사상의 공유·기록 조건을 함께 확인한다.']
c['review']=['파일 열기는 반복 이름 검색을 줄이고 열린 테이블의 사용 상태를 유지한다.','파일 구조를 운영체제가 많이 지원할수록 편의와 구현·확장 제약의 절충이 생긴다.','메모리 사상은 파일 접근을 가상 메모리 참조로 바꾸며 공유 물리 페이지와 쓰기 시 복사는 서로 다른 공유 의미를 가진다.']
c['index_terms']=[{'term':t,'section':s} for t,s in [('열린 파일 테이블','13.1.2'),('권고적 락','13.1.2'),('내부 단편화','13.1.5'),('직접 접근','13.2.2'),('ISAM','13.2.3'),('비순환 그래프','13.3.4'),('참조 계수','13.3.4'),('ACL','13.4.2'),('메모리 사상 파일','13.5.1')]]
c['limitations']=['인쇄592쪽 UPC 색인의 레코드 수·블록 수 연결은 원문 확인 필요로 표시하고 수치를 임의 수정하지 않았다.','Java와 Windows 예제는 원문 코드의 정확한 기호·주석을 보존하기 위해 이미지로 수록했다. 원문 예제의 생략된 동작을 새 코드로 보충하지 않았다.']
c['verification']['visually_checked_pdf_pages'] += [527,530]
c['verification']['notes']=['PDF517~553의 모든 페이지 OCR을 읽고 파일·디렉터리·보호·사상 및 연습문제를 검토했다.','PDF524·549·550의 원문 코드 전체를 직접 보고 크롭했다. PDF527 내부 단편화 예와 PDF530 순차 접근 모사·색인 수치도 이미지로 대조했다.','디렉터리 공유는 PDF537 그림과 본문으로 대조했다. 외부 API 명세로 원문의 매개변수·코드를 수정하지 않았다.']
finish(c)

c=chapter(12,'입출력 시스템',474,515,
 ['포트·버스·컨트롤러의 하드웨어 동작을 응용 인터페이스와 커널 서비스에 연결한다. 폴링·인터럽트·DMA, 봉쇄형·비봉쇄형·비동기식 요청, 버퍼·캐시·스풀의 역할을 구별하고 요청 전체의 처리 경로를 따라간다.'],
 ['하드웨어와 핸드셰이킹 → 장치 드라이버의 추상화 → 응용 I/O 인터페이스 → 커널 서비스 → 이름 변환과 요청 생애 주기 → STREAMS → 성능과 구현 위치'])
c['sections']=[
sec('12.1','개관',474,475,
 p('운영체제는 다양한 속도·기능의 입출력 장치를 관리·제어한다. 인터페이스 표준화는 새 장치의 결합을 쉽게 하지만 장치의 다양성도 계속 커진다. 포트·버스·컨트롤러라는 하드웨어 요소와 **장치 드라이버**라는 소프트웨어 모듈이 이 문제를 다룬다. 드라이버는 구체적인 장치 차이를 감추고 상위 커널 I/O 서브시스템에 일관된 인터페이스를 제공한다.')),
sec('12.2','입출력 하드웨어',475,477,
 p('**포트**는 장치가 연결되는 접점이다. **버스**는 여러 장치가 공유하는 선과 메시지를 교환하는 프로토콜을 포함한다. 장치가 차례로 연결되어 포트로 이어지는 데이지 체인은 통상 버스처럼 동작한다. **컨트롤러**는 포트·버스·장치를 동작시키는 전자장치이며, 단순 칩부터 프로세서·마이크로코드·메모리를 갖춘 HBA까지 다양하다.'),
 p('원문의 PC 구조는 프로세서·메모리와 고속 장치를 PCI 계열 버스로 연결하고 느린 장치는 확장 버스에 연결한다. PCIe는 수신·송신 신호 쌍으로 구성된 레인을 사용하여 양방향 전송을 제공한다. 디스크 자체의 컨트롤러는 프로토콜뿐 아니라 불량 섹터 매핑·선반입·버퍼링·캐싱도 담당한다.')),
sec('12.2.1','메모리 맵드 입출력',477,478,
 p('CPU는 컨트롤러 레지스터에 비트 패턴을 읽고 써서 I/O를 수행한다. 특수 I/O 명령으로 포트를 지정하는 방법과, 장치 제어 레지스터를 프로세서 주소 공간에 대응시키는 **메모리 맵드 I/O**를 구별한다. 후자는 보통의 데이터 전송 명령으로 레지스터를 접근한다. 그래픽 출력의 큰 매핑 영역처럼 많은 데이터를 다룰 때 유용하다.'),
 tab(['레지스터','호스트의 사용과 역할'],[['입력(data-in)','입력 데이터를 읽는다.'],['출력(data-out)','출력할 데이터를 쓴다.'],['상태(status)','명령 완료·입력 준비·오류 여부를 읽는다.'],['제어(control)','명령을 내리거나 통신 방식·검사·속도 등의 모드를 지정한다.']]),
 p('데이터 레지스터가 작더라도 FIFO 칩으로 버퍼를 확장하여 돌발적으로 많은 데이터가 들어오는 상황에 대응할 수 있다.')),
sec('12.2.2','폴링',478,479,
 steps('원문의 바이트 출력 핸드셰이킹','호스트는 busy 비트가 소거될 때까지 검사한다.','명령 레지스터의 쓰기 비트를 설정하고 data-out에 출력 바이트를 쓴다.','command-ready 비트를 설정한다.','컨트롤러는 command-ready를 알아차리고 busy를 설정한다.','컨트롤러는 쓰기 명령과 데이터를 읽어 장치로 출력한다.','완료하면 command-ready·오류·busy 비트를 소거한다. 이 과정은 바이트마다 반복된다.'),
 p('첫 단계의 반복 검사가 **폴링(바쁜 대기)**이다. 기본 검사 자체는 짧지만 준비까지 오래 걸리면 CPU가 다른 유용한 일을 못 한다. 반대로 입력 장치를 너무 늦게 서비스하면 버퍼가 넘쳐 데이터를 잃을 수 있다. 상태가 바뀌었을 때 장치가 CPU에 알리는 인터럽트는 긴 반복 대기를 피하는 방법이다.')),
sec('12.2.3','인터럽트',479,484,
 steps('인터럽트 구동 I/O','드라이버가 I/O를 시작하고 CPU는 다른 명령을 수행한다.','컨트롤러가 입력 준비·출력 완료·오류를 알리는 인터럽트 요청을 보낸다.','CPU는 상태를 저장하고 인터럽트 핸들러로 제어를 옮긴다.','핸들러가 원인을 조사하여 장치를 서비스하고 복귀 명령으로 이전 실행 상태를 회복한다.'),
 fig(c,480,'O12-F01','그림 12.3 인터럽트 구동식 입출력 사이클',(0.17,0.10,0.84,0.519),'CPU 측 처리와 컨트롤러 측의 입출력·완료 신호 사이의 순서를 보여준다.'),
 p('현대 시스템은 인터럽트의 연기, 발생 장치 식별, 여러 우선순위, 예외·트랩 처리를 지원한다. **마스크 불가 인터럽트**는 회복 불가능한 메모리 오류 등의 긴급 상황에, **마스크 가능 인터럽트**는 필요하면 일시 중단할 수 있는 장치 요청에 사용된다. 인터럽트 벡터는 핸들러 주소 테이블을 선택하고, 여러 장치가 한 항목을 공유하면 사슬의 핸들러를 차례로 조사한다. 큰 테이블과 탐색 비용 사이의 절충이다.'),
 p('우선순위는 높은 인터럽트가 낮은 인터럽트 처리를 선점하게 한다. 시간·자원이 제한된 처리기를 1차와 2차로 나누어 1차는 상태 저장·문맥 교환·큐 삽입 등을, 별도로 스케줄되는 2차는 나머지 작업을 수행할 수 있다. 디스크 예에서 다음 I/O 시작은 급하지만 사용자 버퍼로 복사하는 작업은 덜 급하므로 우선순위를 달리한다. 커널 스레드와 우선순위로 이를 구현하면 다중 처리기에서 병렬 핸들링도 가능하다.'),
 p('페이지 폴트는 현재 프로세스를 대기시키고 페이지 입력을 스케줄한 뒤 다른 프로세스를 실행하게 한다. 입력 완료 인터럽트는 대기 프로세스를 준비 큐로 옮긴다. 시스템 콜의 트랩은 인자를 마련하고 사용자 상태를 저장한 뒤 커널 모드의 서비스를 실행하는 경로이다. 원문은 장치 인터럽트와 하드웨어 오류·시스템 콜을 모두 커널 루틴을 촉발하는 용도로 연결한다.'),
 p('인터럽트 처리에도 상태 저장·복귀 등의 비용이 있다. I/O 발생률이 낮을 때 인터럽트를 쓰다가 매우 높아져 폴링이 더 효율적이면 전환하는 혼합 방식도 있다. 따라서 인터럽트가 언제나 폴링보다 빠르다고 단정하지 않는다.')),
sec('12.2.4','직접 메모리 접근(DMA)',484,486,
 p('CPU가 상태를 검사하며 바이트마다 직접 전송하는 **PIO**는 대용량 장치에 CPU 비용이 크다. **DMA**는 이 전송을 특수 컨트롤러에 맡긴다. 호스트는 출발·도착 포인터와 바이트 수를 담은 명령 블록을 메모리에 쓰고 그 주소를 DMA에 알려준다. 비연속 주소 목록을 사용하는 분산-수집 방식은 한 명령으로 여러 전송을 수행한다.'),
 steps('DMA 전송','장치 컨트롤러가 DMA-request로 전송을 요청한다.','DMA 컨트롤러가 메모리 버스를 확보하고 주소를 놓은 뒤 DMA-acknowledge를 보낸다.','장치가 워드를 전송하고 요청 신호를 제거한다.','전체 전송이 끝나면 DMA가 CPU에 인터럽트로 완료를 알린다.'),
 fig(c,485,'O12-F02','그림 12.6 DMA 전송의 단계',(0.235,0.532,0.86,0.941),'원문의 주소 x, 전송량 c 및 완료 인터럽트의 관계를 보존한다. 주소는 증가하고 c는 0이 될 때까지 감소한다.'),
 p('DMA가 버스를 쓰는 동안 CPU는 캐시에는 접근할 수 있어도 주메모리 접근이 잠시 제한된다. 이 **사이클 스틸링**은 CPU를 늦추지만 전체 I/O 성능을 개선한다. 커널 버퍼를 거치면 사용자 공간으로 다시 복사하는 이중 버퍼링 비용이 있고, 직접 사용자 공간을 이용하면 전송 도중 수정에 주의해야 한다. DVMA는 가상 주소로 메모리 맵드 장치 사이의 전송을 지원한다. 일반 프로세스의 직접 I/O는 성능상 이익이 있어도 보안·안정성을 해칠 수 있어 범용 운영체제는 메모리와 장치를 보호한다.')),
sec('12.2.5','입출력 하드웨어 요약',486,487,
 p('컨트롤러·포트·레지스터가 장치와 통신하는 기반이다. 호스트와 컨트롤러는 핸드셰이킹하고, 준비 상태는 폴링 또는 인터럽트로 확인하며, 큰 전송은 DMA로 위임한다. 이 하드웨어 차이를 상위의 일관된 인터페이스에 어떻게 수용하는지가 다음 절의 주제이다.')),
sec('12.3','응용 입출력 인터페이스',487,490,
 p('추상화·캡슐화·계층화로 장치를 대표 범주와 표준 함수 집합으로 표현한다. 장치 드라이버가 이 함수를 구체적으로 구현하므로 상위 I/O 서브시스템은 하드웨어 차이에 덜 의존한다. 새 하드웨어는 기존 컨트롤러 인터페이스를 구현하거나 새 드라이버를 제공할 수 있다. 다만 드라이버 인터페이스는 운영체제마다 달라 각 운영체제용 드라이버가 필요하다.'),
 tab(['원문의 분류 기준','구분'],[['전송 단위','문자 스트림 / 블록'],['접근 순서','순차 / 임의 접근'],['다른 사건과의 조율','동기식 / 비동기식 장치'],['사용자 수','공유 가능 / 전용'],['속도','지연·탐색 시간·전송률·연산 간 지연'],['입출력 방향','읽기·쓰기 / 읽기 전용 / 한 번 쓰기']]),
 p('운영체제는 블록·문자 스트림·메모리 맵드 파일·네트워크 소켓·클록/타이머 등의 범주를 제공한다. 범주에 없는 고유 명령은 UNIX의 **ioctl()** 같은 호출로 전달할 수 있다. 원문의 세 인자는 장치 식별자, 명령을 나타내는 정수, 임의 자료구조를 가리키는 포인터이다. UNIX/Linux의 주(major) 번호는 드라이버·장치 유형을, 부(minor) 번호는 구체적 인스턴스를 선택한다.')),
sec('12.3.1','블록 장치와 문자 장치',490,491,
 p('블록 인터페이스는 read·write·seek로 블록 장치를 제어하며 응용은 보통 파일 시스템을 거쳐 사용한다. 자체 버퍼·잠금을 쓰는 데이터베이스에는 운영체제의 중복 버퍼링·잠금이 부담이나 충돌이 될 수 있다. raw 접근은 장치 제어를 응용에 맡기고, **direct I/O**는 파일을 유지하되 버퍼링·잠금을 하지 않는 절충으로 소개된다.'),
 p('**메모리 맵드 파일**은 파일을 가상 주소에 대응시켜 메모리 읽기·쓰기로 접근한다. 해당 주소가 참조될 때 데이터가 실제로 메모리에 올라와 요구 페이징을 이용한다. 실행 파일 적재와 스왑 접근에도 이러한 인터페이스가 쓰인다. 문자 장치는 put·get처럼 한 문자씩 전송하고 상위 라이브러리가 줄 단위·편집·버퍼링을 제공할 수 있다. 키보드·마우스·모뎀이나 선형 바이트 스트림 출력 장치에 적합하다.')),
sec('12.3.2','네트워크 장치',491,491,
 p('네트워크는 디스크의 read-write-seek와 다른 **소켓 인터페이스**를 사용한다. 소켓 생성, 원격 주소와 연결, 연결 완료 확인, 패킷 교환을 제공하여 하드웨어·프로토콜 내부를 감춘다. select()는 여러 소켓 가운데 수신할 데이터나 송신 여유가 있는 소켓을 알려 주어 응용의 바쁜 대기를 피한다. 원문은 FIFO·STREAMS·메시지 큐·소켓 등 다양한 IPC 방식의 존재도 설명한다.')),
sec('12.3.3','클록과 타이머',492,493,
 p('클록·타이머는 현재 시각, 지난 시간, 지정 시각의 연산 실행을 제공한다. **프로그램 가능 인터벌 타이머**는 한 번 또는 주기적으로 인터럽트를 만들며 타임 슬라이스 종료, 더티 버퍼 기록, 네트워크 시간 제한 등에 쓰인다. 소프트웨어 가상 클록은 제한된 하드웨어 채널로 더 많은 요청을 지원한다.'),
 steps('가상 타이머 관리','요청을 마감시간순으로 정렬한다.','하드웨어 타이머를 가장 이른 마감시간으로 설정한다.','인터럽트가 발생하면 요청자에게 알리고 다음 마감시간으로 다시 설정한다.'),
 p('타이머 해상도에는 하드웨어뿐 아니라 가상 클록 유지 비용도 작용한다. 시스템 시각 오차는 NTP 같은 프로토콜로 보정할 수 있다는 것이 원문의 설명이다. 읽을 수 있는 고정밀 카운터는 정확한 간격 측정에 사용되지만 반드시 인터럽트 생성에도 쓰이는 것은 아니다.')),
sec('12.3.4','봉쇄형과 비봉쇄형 입출력',493,495,
 tab(['방식','호출과 데이터·완료 관계'],[['봉쇄형(blocking)','호출 스레드를 대기 큐로 옮기고 I/O가 끝나면 실행 가능한 상태로 돌린다. 코드 작성이 간단하다.'],['비봉쇄형(nonblocking)','오래 멈추지 않고 그 시점에 가능한 데이터 전송량을 반환한다. 전체 또는 일부 데이터일 수 있다.'],['비동기식(asynchronous)','요청을 제출한 뒤 즉시 돌아와 다른 일을 한다. 나중에 전체 작업 완료를 변수·시그널·소프트웨어 인터럽트·콜백 등으로 알린다.']]),
 p('원문은 비봉쇄형 읽기가 지금 얻을 수 있는 데이터를 반환하는 반면 비동기식 읽기는 나중에 완전한 데이터를 제공하도록 요청한다는 차이를 강조한다. 여러 스레드를 사용하면 일부는 봉쇄형 호출로 기다리고 나머지는 연산할 수도 있다. select()에 대기시간 0을 주면 봉쇄 없이 상태만 검사하지만 실제 전송에는 뒤이은 읽기·쓰기가 필요하다.'),
 p('운영체제 내부에서도 쓰기나 네트워크 전송을 버퍼링한 뒤 먼저 응용에 복귀할 수 있다. 미기록 요청은 크래시 때 손실될 수 있어 기록 시간 제한과 명시적 플러시 방법을 둔다. 읽기는 아직 매체에 쓰지 않은 버퍼 내용과도 일관되어야 하며, 같은 파일을 여러 스레드가 접근하면 구현에 따라 잠금 프로토콜이 필요하다.')),
sec('12.3.5','벡터형 입출력',495,495,
 p('**벡터형 I/O**는 한 시스템 콜로 여러 버퍼에 대한 작업을 수행하는 분산-수집 인터페이스이다. 원문의 UNIX readv 예처럼 여러 개별 호출과 중간 대형 버퍼 복사를 줄여 문맥 교환·시스템 콜 비용을 낮춘다. 일부 구현은 전체 작업의 원자성을 보장하여 같은 버퍼의 동시 I/O에 의한 오염을 막는다. 원자성은 모든 버전에 무조건 있다고 확대하지 않는다.')),
sec('12.4.1','I/O 스케줄링',495,496,
 p('I/O 스케줄링은 요청 실행 순서를 정한다. 장치별 대기 큐를 재정렬하여 성능·공정성·평균 응답 시간을 개선한다. 원문 예는 헤드가 시작 부분에 있고 요청들이 끝·시작·중간 순서로 들어오면 2→3→1로 바꾸는 것이다. 긴급한 페이징 요청이 응용 I/O보다 우선할 수도 있다. 비동기 요청은 동시에 여러 개가 진행되므로 장치 상태 테이블의 종류·주소·상태와 해당 큐를 함께 추적한다.')),
sec('12.4.2','버퍼링',496,498,
 p('**버퍼**는 두 장치 또는 장치와 프로그램 사이에서 전송 중인 데이터를 임시 저장하는 메모리이다. 첫째 목적은 생산자·소비자의 속도 차이를 완충하는 것이다. 이중 버퍼링에서는 한 버퍼를 장치에 기록하는 동안 다른 버퍼를 수신 데이터로 채워 두 동작의 타이밍을 분리한다. 둘째는 전송 크기 차이이다. 메시지를 작은 패킷으로 나누거나 수신 패킷을 조합할 때 버퍼를 쓴다.'),
 p('셋째는 **복제 시맨틱**이다. write() 이후 응용이 자기 버퍼를 수정해도 매체에는 호출 시점의 버전이 기록되어야 한다. 간단한 구현은 응용에 복귀하기 전에 커널 버퍼로 복사하고 그 사본을 기록하는 것이다. 복사 비용이 있지만 의미가 간단하다. 원문은 가상 메모리 매핑과 쓰기 시 복사 보호로 비슷한 효과를 더 효율적으로 얻을 수도 있다고 설명한다.')),
sec('12.4.3','캐싱',498,498,
 p('**캐시**는 자주 사용할 자료의 사본을 빠른 저장 공간에 두는 것이다. 원문의 구분에서 버퍼는 전송 데이터의 유일한 보관 장소일 수 있고 캐시는 다른 곳의 원본에 대한 사본이다. 기능은 다르지만 한 메모리 영역이 두 역할을 겸할 수 있다. 파일 I/O는 먼저 버퍼 캐시를 검사하여 실제 I/O를 피하거나 미룰 수 있고, 지연된 쓰기를 모아 큰 단위로 스케줄할 수 있다.')),
sec('12.4.4','스풀링 및 장치 예약',498,499,
 p('**스풀**은 프린터처럼 여러 작업을 뒤섞어 출력할 수 없는 장치의 출력 버퍼이다. 프로그램별 출력을 별도 보조저장장치 파일에 모으고 완성된 작업을 큐에 넣어 하나씩 출력한다. 디먼이나 커널 스레드가 관리하며 작업 열거·취소·중지 기능을 제공한다.'),
 p('전용 장치는 한 프로그램에 할당하고 명시적으로 반납하게 하거나 열린 핸들을 하나로 제한할 수도 있다. 프로세스 간 협조적 배타 접근을 지원하는 방식도 있다. 이러한 장치 예약에서 생길 수 있는 교착 상태는 원문의 해당 시스템 예에서 응용의 책임이다.')),
sec('12.4.5','오류 처리',499,500,
 p('일시적 오류는 읽기·전송 재시도 등으로 복구할 수 있지만 핵심 장치의 영구 고장은 완전히 극복하기 어렵다. 시스템 콜은 성공·실패와 추가 오류 정보를 반환하며 UNIX errno가 예로 제시된다. SCSI의 sense key·sense code·qualifier·오류 로그는 더 세부적인 원인을 표현하지만 운영체제가 모든 하드웨어 정보를 응용에 전달하는 것은 아니다.')),
sec('12.4.6','입출력 보호',500,501,
 p('입출력 명령을 특권 명령으로 두어 사용자가 직접 실행하지 못하게 하고, 시스템 콜을 받은 운영체제가 요청의 유효성을 검사한다. 메모리 맵드 I/O·포트 영역도 메모리 보호 대상이다. 다만 그래픽 성능처럼 직접 접근을 허용할 필요가 있으면 커널은 영역을 적절히 할당하고 잠금으로 중복 사용을 제어해야 한다.')),
sec('12.4.7','커널 자료구조',501,502,
 p('커널은 열린 파일·네트워크 연결·문자 통신 등의 상태를 자료구조로 관리한다. UNIX의 파일 인터페이스는 일반 파일·raw 장치·프로세스 주소 공간을 모두 read()로 접근하게 하지만 실제 처리는 다르다. 열린 파일 레코드의 디스패치 테이블은 객체 유형에 맞는 읽기·쓰기·select·ioctl·close 함수를 가리킨다.'),
 p('원문은 독립적인 I/O 관리자와 메시지 전달 방식도 비교한다. 메시지 횟수가 늘어 비용이 생기지만 커널을 작게 하고 구조·설계의 유연성을 높일 수 있다. 이 비교는 원문이 설명하는 구현 사례의 범위에서 이해한다.')),
sec('12.4.8','전원 관리',502,504,
 p('운영체제는 부하에 맞춰 프로세스를 이동시키거나 장치·CPU 코어를 유휴 상태로 만들어 전력·발열·냉각 비용을 줄인다. 일시 중단한 코어의 상태는 저장하고 재개 시 복원한다. 모바일 운영체제에서는 배터리 수명이 특히 중요하다.'),
 tab(['원문의 Android 기능','역할'],[['전원 축소(power collapse)','개별 구성요소를 끄고 CPU를 깊은 슬립 상태로 둔다. 외부 자극·인터럽트에는 반응하여 빠르게 재개한다.'],['구성요소 수준 전원 관리','장치 트리의 부모·자식 관계와 드라이버의 사용 여부를 추적한다. 자식들이 모두 유휴이면 버스 등 상위 구성요소도 끌 수 있다.'],['wakelock','필요한 동안 응용이 획득하여 전원 축소 진입을 막고 작업이 끝나면 해제한다.']]),
 p('전체 시스템은 부팅 때뿐 아니라 실행 중 장치 추가·제거와 상태·오류·전력 변화를 관리해야 한다. **ACPI**는 커널이 호출할 수 있는 하드웨어 관리 루틴을 제공한다. 원문의 정지 예에서는 커널→장치 드라이버→ACPI 루틴→장치의 순서로 지시한다.')),
sec('12.4.9','커널 입출력 서브시스템 요약',504,504,
 p('커널 I/O 서브시스템은 이름·접근 제어·연산 허용 여부·파일 공간·장치 할당·버퍼/캐시/스풀·스케줄링·상태 감시·오류/복구·드라이버 초기화·전원 관리를 조정한다. 상위 계층은 드라이버가 제공하는 공통 인터페이스로 장치를 사용한다.')),
sec('12.5','입출력 요구를 하드웨어 연산으로 변환',505,507,
 p('파일 이름은 파일 시스템의 디렉터리와 할당 정보로 연결된다. FAT는 이름을 할당 테이블 항목과 블록으로, UNIX는 이름을 inode와 할당 정보로 매핑한다. UNIX에서는 마운트 테이블의 가장 긴 일치 접두어가 장치를 정하고, 주 장치 번호는 드라이버를, 부 장치 번호는 장치 테이블 항목을 선택하며, 여기에서 컨트롤러 포트·메모리 주소를 얻는다. 여러 검색 테이블은 유연성과 동적 드라이버 적재를 제공하지만 잠금·오류 처리도 복잡해진다.'),
 steps('원문의 봉쇄형 read 생애 주기','열린 파일의 디스크립터로 read를 요청하고 커널이 인자를 검사한다.','버퍼 캐시에 데이터가 있으면 바로 반환한다. 없으면 프로세스를 대기시키고 I/O를 스케줄한다.','드라이버가 커널 버퍼를 확보하고 컨트롤러 레지스터에 명령을 기록한다.','장치가 데이터를 전송한다. 원문의 가정에서는 DMA가 완료 인터럽트를 발생시킨다.','벡터를 통해 핸들러가 드라이버에 알리고 드라이버는 완료 요청을 식별하여 I/O 서브시스템에 통지한다.','커널이 사용자 버퍼로 데이터를 옮기고 프로세스를 준비 큐로 옮긴다.','스케줄러가 CPU를 할당하면 프로세스가 시스템 콜에서 복귀한다.'),
 fig(c,506,'O12-F03','그림 12.14 입출력 요청의 생애 주기',(0.17,0.525,0.90,0.94),'사용자·커널·드라이버·인터럽트 핸들러·컨트롤러 사이의 요청과 완료 경로를 원문 그대로 보존한다.')),
sec('12.6','STREAMS',507,509,
 p('**STREAMS**는 응용이 드라이버 코드의 파이프라인을 동적으로 조립하는 UNIX의 기법이다. 스트림은 사용자 프로세스와 장치 드라이버 사이의 완전 양방향 연결이며, 스트림 헤드·0개 이상의 모듈·드라이버 엔드로 구성된다. 각 요소에는 읽기·쓰기 큐가 있고 메시지 전달로 데이터를 교환한다. ioctl()로 모듈을 삽입할 수 있어 편집·네트워크 처리 등을 재사용한다.'),
 fig(c,508,'O12-F04','그림 12.15 STREAMS 구조',(0.29,0.095,0.76,0.474),'헤드·모듈·드라이버 엔드의 읽기 큐와 쓰기 큐가 반대 방향으로 메시지를 전달하는 구조이다.'),
 p('흐름 제어를 사용하는 큐는 메시지를 버퍼링하고 여유가 없으면 새 메시지를 거절하여 인접 큐의 오버플로를 막는다. write/read는 바이트 스트림을, putmsg/getmsg는 메시지를 응용에 제공한다. 내부는 비동기적으로 동작하지만 프로세스가 헤드에 쓸 공간이나 읽을 데이터가 없으면 봉쇄된다. 드라이버 엔드는 외부 인터럽트에 응답해야 하므로 기다릴 수 없고 장치 버퍼가 차면 들어오는 메시지를 버릴 수 있다. 메시지 경계·제어 정보와 모듈 재사용이 원문의 장점이다.')),
sec('12.7','성능',509,513,
 p('I/O 비용은 장치 시간에만 있지 않다. 드라이버 실행·봉쇄/해제·문맥 교환·인터럽트·캐시 영향·장치/메모리/커널/사용자 사이의 복사가 CPU와 메모리 버스에 부하를 준다. 원격 로그인에서 문자 하나를 전달하고 다시 반향하는 예는 작은 데이터도 여러 계층과 문맥 교환을 거칠 수 있음을 보인다. 프런트 엔드 처리기와 I/O 채널은 이 부담을 주 CPU에서 덜어 준다.'),
 bullets('문맥 교환·복사·인터럽트 빈도를 줄인다. 큰 전송, 지능형 컨트롤러, 바쁜 대기가 작은 폴링을 적절히 이용한다.','DMA·채널로 CPU 부담을 낮추고 I/O와 연산을 중첩한다.','원시 연산을 장치 하드웨어에서 병렬 수행하고 CPU·메모리·버스·I/O 부하가 균형을 이루게 한다.'),
 tab(['구현 위치','원문의 장점','비용·제약'],[['응용 코드','신축적이며 실험·디버깅이 쉽고 버그가 시스템 전체를 중단시킬 가능성이 작다.','문맥 교환 비용, 커널 내부 서비스 이용의 제약'],['커널','성능을 높이고 커널 서비스와 결합할 수 있다.','커널이 커지고 복잡해지며 오류가 크래시·데이터 손상으로 이어질 수 있다.'],['장치·컨트롤러 하드웨어','가장 높은 성능을 지향한다.','개발이 오래 걸리고 수정·개선·부하에 따른 정책 변경이 어렵다.']]),
 p('원문의 저장장치 성능 그림은 용량과 지연시간이라는 서로 다른 축에서 캐시·DRAM·NVM·SSD·HDD와 네트워크 지연을 비교한다. 큰 용량이 낮은 지연을 뜻하지 않으며 네트워크를 통한 접근은 추가 지연을 가진다는 관계를 읽는다. 수치가 아닌 도표상의 관계 범위에서 정리한다.')),
sec('12.8','요약과 원문 연습문제의 점검 범위',513,515,
 p('장말 문제는 기능을 컨트롤러에 둘 때의 장단점, 핸드셰이킹 비트, 폴링·인터럽트·혼합 전략, DMA의 병행성, CPU/버스/장치 속도의 균형, STREAMS의 엔드와 모듈을 점검한다. 새 프로토콜·풀이를 만들지 않는다. 추가 자료·참고문헌의 범위는 확인했으나 외부 설명을 가져오지 않았다.'))]
c['comparisons']=[{'title':'봉쇄형·비봉쇄형·비동기식 I/O','source':src(493,495),'headers':['방식','반환과 완료'],'rows':[['봉쇄형','완료를 기다려 결과를 받는다.'],['비봉쇄형','지금 가능한 전송량을 반환한다.'],['비동기식','먼저 돌아온 후 전체 요청 완료를 별도로 알린다.']]},{'title':'버퍼·캐시·스풀','source':src(496,499),'headers':['개념','목적'],'rows':[['버퍼','전송 중 임시 보관, 속도·크기 차이와 복제 시맨틱 지원'],['캐시','다른 곳에 있는 데이터의 빠른 사본으로 재사용'],['스풀','섞어 처리할 수 없는 장치에 작업별 출력을 모아 순차 전달']]}]
c['key_points']=['폴링은 상태를 반복 검사하고 인터럽트는 상태 변화를 통지한다. 발생률·대기 길이와 처리 비용에 따라 선택한다.','DMA는 CPU의 전송 부담을 줄이지만 메모리 버스 사용·버퍼 보호·추가 복사 문제를 함께 고려한다.','비봉쇄형의 현재 가능한 결과와 비동기식의 나중 완료 통지를 구별한다.','버퍼링·캐싱·스풀링은 목적이 다르며 같은 영역이 버퍼와 캐시 역할을 겸할 수 있다.','이름→드라이버→컨트롤러와 요청→완료 인터럽트→프로세스 재개를 연결한다.']
c['review']=['응용은 장치를 직접 제어하기보다 드라이버와 커널 서비스의 표준 인터페이스를 사용한다.','일관성·보호·전력 관리 역시 I/O 서브시스템의 역할이다.','STREAMS는 양방향 큐와 메시지·흐름 제어로 모듈을 결합한다.','성능은 장치 속도뿐 아니라 문맥 교환·인터럽트·복사·계층 간 이동 비용에 좌우된다.']
c['index_terms']=[{'term':t,'section':s} for t,s in [('메모리 맵드 I/O','12.2.1'),('폴링','12.2.2'),('인터럽트 벡터','12.2.3'),('DMA','12.2.4'),('비동기 I/O','12.3.4'),('복제 시맨틱','12.4.2'),('스풀링','12.4.4'),('wakelock','12.4.8'),('STREAMS','12.6')]]
